// German (de-AT) texts of the in-app guide (concept-guide.ts), keyed by the English text they translate: textOf()
// looks a card's text up here for 'de' and falls back to English when a key is missing (test/unit/concept-guide.test.ts
// checks that none is). Rewrite an entry when its English text changes. Used by concept-guide.ts.
export const GUIDE_DE: Readonly<Record<string, string>> = {
  "Every task goes through a role": "Jede Aufgabe läuft über eine Rolle",
  "Six fixed roles do the work: the Orchestrator coordinates, five work roles carry it out, each in a chat you can see.": "Sechs feste Rollen erledigen die Arbeit: der Orchestrator koordiniert, fünf Arbeitsrollen führen sie aus, jede in einem Chat, den du siehst.",
  "The roles are always the same: Orchestrator, Strategist, Scout, Artisan, Sentinel, Herald. Nobody creates a new one: missing know-how becomes a skill. Router, Judge and Scribe are gone: the Orchestrator splits independent requests, Sentinel gives the independent verdict, Artisan writes documents and brain notes with a skill.": "Die Rollen sind immer dieselben: Orchestrator, Strategist, Scout, Artisan, Sentinel, Herald. Niemand legt eine neue an: fehlendes Know-how wird zu einem Skill. Router, Judge und Scribe gibt es nicht mehr: der Orchestrator teilt unabhängige Anfragen auf, Sentinel gibt das unabhängige Urteil, Artisan schreibt Dokumente und Brain-Notizen mit einem Skill.",
  "Work starts only from the Orchestrator: Ctrl+N puts the cursor in its column (\"What do you want to do?\"), it picks the role and the skills; the chat is born with the role’s engine, its tier’s model and the role’s instructions.": "Arbeit startet nur beim Orchestrator: Strg+N setzt den Cursor in seine Spalte („Was willst du tun?“), er wählt Rolle und Skills; der Chat entsteht mit der Engine der Rolle, dem Modell ihrer Stufe und den Anweisungen der Rolle.",
  "The Orchestrator reads the list of roles, asks for the fitting skills and opens the work naming the role: the role decides engine, model and effort, nothing overrides them.": "Der Orchestrator liest die Liste der Rollen, fragt nach den passenden Skills und eröffnet die Arbeit mit Nennung der Rolle: die Rolle bestimmt Engine, Modell und Aufwand, nichts überschreibt sie.",
  "A working role delegates a part to another role it may launch: the child is a visible chat under its parent, never a hidden sub-agent, and never gets more permissions than its parent.": "Eine arbeitende Rolle delegiert einen Teil an eine andere Rolle, die sie starten darf: das Kind ist ein sichtbarer Chat unter seinem Elternchat, nie ein versteckter Subagent, und bekommt nie mehr Berechtigungen als sein Elternchat.",
  "Every role closes its job with a report: outcome, summary, output and the contract’s criteria with their evidence. It is a self-report, not an independent check.": "Jede Rolle schließt ihre Aufgabe mit einem Bericht ab: Ergebnis, Zusammenfassung, Output und die Kriterien des Vertrags mit ihren Belegen. Das ist eine Selbstauskunft, keine unabhängige Prüfung.",
  "Work-role chats have a \"run\" with counters and cost; the Orchestrator and chats started without a role (with your permissions) do not.": "Chats von Arbeitsrollen haben einen „Run“ mit Zählern und Kosten; der Orchestrator und Chats ohne Rolle (mit deinen Berechtigungen) nicht.",
  "The app improves the roles by itself: texts and skills at once, with \"Undo\"; model tier, tools and permissions only with your yes in Memory → Proposals, as a trial version.": "Die App verbessert die Rollen selbst: Texte und Skills sofort, mit „Rückgängig“; Modellstufe, Tools und Berechtigungen nur mit deinem Ja in Gedächtnis → Vorschläge, als Probeversion.",
  "Like a team with fixed roles: the coordinator assigns, each does their part in plain sight and comes back with the result; when know-how is missing, you write the manual, you do not hire someone else.": "Wie ein Team mit festen Rollen: der Koordinator teilt zu, jeder macht seinen Teil vor aller Augen und kommt mit dem Ergebnis zurück; fehlt Know-how, schreibst du das Handbuch, statt jemand Neuen einzustellen.",
  "Task": "Aufgabe",
  "Orchestrator": "Orchestrator",
  "Role and skills": "Rolle und Skills",
  "Result": "Ergebnis",
  "Improvement": "Verbesserung",
  "Data shape": "Datenform",
  "AgentProfile { id, name, purpose, instructions, engine, model | null, effort?, tools, permissionCeiling, tier, tierMax, launches, skills, version, activeVersion, trial?, userLocked }.": "AgentProfile { id, name, purpose, instructions, engine, model | null, effort?, tools, permissionCeiling, tier, tierMax, launches, skills, version, activeVersion, trial?, userLocked }.",
  "Files": "Dateien",
  "userData/roles.json (the six roles and Pulse) and role-history.json (each role’s versions).": "userData/roles.json (die sechs Rollen und Battito) und role-history.json (die Versionen jeder Rolle).",
  "Thresholds and limits": "Schwellen und Grenzen",
  "Delegation: depth 2 and 5 running children per parent by default (Settings → Roles and delegation).": "Delegation: standardmäßig Tiefe 2 und 5 laufende Kinder pro Elternchat (Einstellungen → Rollen und Delegation).",
  "Internal tools": "Interne Tools",
  "agent_catalog (the roles), skills_suggest (the skills), app_create_chat with roleId (opens the work), agent_report (the final report).": "agent_catalog (die Rollen), skills_suggest (die Skills), app_create_chat mit roleId (eröffnet die Arbeit), agent_report (der Abschlussbericht).",
  "On Codex and Cursor the ban on the engine’s internal sub-agents is written in the instructions, not enforced by the app.": "Auf Codex und Cursor steht das Verbot der internen Subagenten der Engine in den Anweisungen, die App erzwingt es nicht.",
  "Several independent requests in one message: the Orchestrator opens one chat per request itself, all at once; the app does not send it incoming work by itself.": "Mehrere unabhängige Anfragen in einer Nachricht: der Orchestrator eröffnet selbst einen Chat pro Anfrage, alle auf einmal; die App schickt ihm eingehende Arbeit nicht von selbst.",
  "Delegation between roles": "Delegation zwischen Rollen",
  "A role hands part of its task to another role: the child is a visible chat under it, with a contract, and comes back with one result.": "Eine Rolle gibt einen Teil ihrer Aufgabe an eine andere Rolle ab: das Kind ist ein sichtbarer Chat darunter, mit einem Vertrag, und kommt mit einem Ergebnis zurück.",
  "A delegation starts 1 to 10 child chats at once, each with a self-contained contract: goal, expected output, done-when criteria, context. The child never reads the parent’s conversation.": "Eine Delegation startet 1 bis 10 Kind-Chats auf einmal, jeden mit einem eigenständigen Vertrag: Ziel, erwarteter Output, Fertig-wenn-Kriterien, Kontext. Das Kind liest nie die Unterhaltung des Elternchats.",
  "Permissions only go down: a child never gets more tools or permissions than its parent and works in its folder (or a worktree of the same repository); a request beyond the parent’s permissions is refused and says so in the chat. By default every role may do everything, so a planner (Strategist) also launches the roles that change something (Artisan, Sentinel, Herald); if you narrowed the parent, a child that needs more does not start: the parent writes it in its result and the Orchestrator starts it.": "Berechtigungen gehen nur nach unten: ein Kind bekommt nie mehr Tools oder Berechtigungen als sein Elternchat und arbeitet in dessen Ordner (oder einem Worktree desselben Repositorys); eine Anfrage über die Berechtigungen des Elternchats hinaus wird abgelehnt und das steht im Chat. Standardmäßig darf jede Rolle alles, also startet auch ein Planer (Strategist) die Rollen, die etwas ändern (Artisan, Sentinel, Herald); hast du den Elternchat eingeschränkt, startet ein Kind, das mehr braucht, nicht: der Elternchat schreibt es in sein Ergebnis und der Orchestrator startet es.",
  "Depth and running children are your limits (Settings → Roles and delegation); a delegation over the limit is refused and the parent shows \"Limit\".": "Tiefe und laufende Kinder sind deine Grenzen (Einstellungen → Rollen und Delegation); eine Delegation über der Grenze wird abgelehnt und der Elternchat zeigt „Grenze“.",
  "A child’s doubt goes to its parent first; only what needs a person reaches you (a permission, an irreversible or external action, a choice that changes the goal), once, in the chat you are looking at.": "Ein Zweifel des Kinds geht zuerst an seinen Elternchat; nur was einen Menschen braucht, erreicht dich (eine Berechtigung, eine unumkehrbare oder externe Aktion, eine Wahl, die das Ziel ändert), einmal, im Chat, den du gerade ansiehst.",
  "In the Grindhouse each child is a card on its parent’s thread: task, character, skills, model, its real steps (the engine’s plan and its actions), its state. A click opens it into the whole chat; \"Vai alla chat\" puts it in focus.": "Im Grindhouse ist jedes Kind eine Karte im Thread seines Elternchats: Aufgabe, Figur, Skills, Modell, seine echten Schritte (der Plan der Engine und ihre Aktionen), sein Zustand. Ein Klick öffnet es zum ganzen Chat; „Zum Chat“ setzt den Fokus darauf.",
  "You can write in any child: the Orchestrator and the parent learn it in your words, so nobody undoes what you asked; if you change the goal, the child says so in its result.": "Du kannst in jedes Kind schreiben: der Orchestrator und der Elternchat erfahren es in deinen Worten, damit niemand rückgängig macht, worum du gebeten hast; änderst du das Ziel, sagt das Kind es in seinem Ergebnis.",
  "The child closes with a report: the result reaches the parent as a message; the Orchestrator sees only the state. A chat the Orchestrator opened itself reports to it the same way.": "Das Kind schließt mit einem Bericht ab: das Ergebnis erreicht den Elternchat als Nachricht; der Orchestrator sieht nur den Zustand. Ein Chat, den der Orchestrator selbst eröffnet hat, berichtet ihm genauso.",
  "Like a site foreman handing jobs to his crew: each has a job sheet, nobody holds keys the foreman lacks, and questions go through him first.": "Wie ein Polier, der seiner Partie Aufträge gibt: jeder hat einen Arbeitszettel, niemand hat Schlüssel, die der Polier nicht hat, und Fragen gehen zuerst über ihn.",
  "Parent": "Elternchat",
  "Delegation": "Delegation",
  "Visible children": "Sichtbare Kinder",
  "Report": "Bericht",
  "ChatSummary.parentId and delegation { role, goal, doneWhen, at, tools?, result?, originalGoal? }.": "ChatSummary.parentId und delegation { role, goal, doneWhen, at, tools?, result?, originalGoal? }.",
  "Where it lives": "Wo es liegt",
  "Chat MCP tools: agent_delegate, agent_report, agent_children, agent_ask_parent, agent_answer_child (pre-approved).": "MCP-Tools des Chats: agent_delegate, agent_report, agent_children, agent_ask_parent, agent_answer_child (vorab genehmigt).",
  "The roles and their editor": "Die Rollen und ihr Editor",
  "A role is a fixed profile with instructions, engine, model tier, the roles it may launch and its default skills; by default it may do everything, and you narrow its permissions from its card.": "Eine Rolle ist ein festes Profil mit Anweisungen, Engine, Modellstufe, den Rollen, die sie starten darf, und ihren Standard-Skills; standardmäßig darf sie alles, und du schränkst ihre Berechtigungen auf ihrer Karte ein.",
  "Strategist plans, Scout searches and reads, Artisan builds and writes documents and brain notes, Sentinel verifies and, when nothing can be run, judges from the evidence, Herald communicates.": "Strategist plant, Scout sucht und liest, Artisan baut und schreibt Dokumente und Brain-Notizen, Sentinel prüft und urteilt, wenn nichts ausgeführt werden kann, anhand der Belege, Herald kommuniziert.",
  "In Agents each role has its page: \"Edit\" changes instructions, skills, engine, model, tier, launchable roles and maximum context; name, purpose and character stay the role’s.": "Unter Agenten hat jede Rolle ihre Seite: „Bearbeiten“ ändert Anweisungen, Skills, Engine, Modell, Stufe, startbare Rollen und maximalen Kontext; Name, Zweck und Figur bleiben die der Rolle.",
  "Permissions: by default every role has every tool and no limit (\"Everything allowed\"), so you find no refused calls and no useless popups. The role’s \"Permissions\" card (or \"Edit permissions\" on the back of its card) narrows them: one switch per tool class and a limit among four, each with its \"?\". Every save is a version; \"Restore defaults\" goes back to everything allowed.": "Berechtigungen: standardmäßig hat jede Rolle jedes Tool und keine Grenze („Alles erlaubt“), so findest du keine abgelehnten Aufrufe und keine unnötigen Pop-ups. Die Karte „Berechtigungen“ der Rolle (oder „Berechtigungen bearbeiten“ auf der Rückseite ihrer Karte) schränkt sie ein: ein Schalter pro Tool-Klasse und eine von vier Grenzen, jede mit ihrem „?“. Jedes Speichern ist eine Version; „Standard wiederherstellen“ geht zurück auf alles erlaubt.",
  "\"Restore default\" brings the role back as the app ships it, after a confirmation. The roles are fixed: they are not created, imported or exported (the whole brain is shared instead, Settings → \"Condividi il brain\").": "„Standard wiederherstellen“ bringt die Rolle nach einer Bestätigung so zurück, wie die App sie ausliefert. Die Rollen sind fest: Sie werden weder erstellt noch importiert oder exportiert (stattdessen wird das ganze Brain geteilt, Einstellungen → „Condividi il brain“).",
  "Every behaviour change is a new version: the page shows the latest ones and brings an older one back with a click.": "Jede Verhaltensänderung ist eine neue Version: die Seite zeigt die letzten und holt eine ältere mit einem Klick zurück.",
  "A role without its own model takes the model of the Model routing row that matches the work on its engine (and its effort, when the role names none); else the tier (light, mid, top) becomes a model per engine: your choice in Settings, else the brain’s model registry. Sentinel is independent because it starts in a new session without the parent’s reasoning, not because they switch model.": "Eine Rolle ohne eigenes Modell nimmt das Modell der Zeile im Modell-Routing, die zur Arbeit auf ihrer Engine passt (und deren Aufwand, wenn die Rolle keinen nennt); sonst wird die Stufe (leicht, mittel, hoch) zu einem Modell pro Engine: deine Wahl in den Einstellungen, sonst die Modellregistry des Brain. Sentinel ist unabhängig, weil es in einer neuen Sitzung ohne die Überlegungen des Elternchats startet, nicht weil das Modell wechselt.",
  "Tools come in classes: a role limited to read-only commands has a writing command refused in the chat (when a chat that may run it delegated it, you decide); one that reads, or a node script listed in read-only-tools.md in the brain, reaches you as a permission without \"always\". When a skill passed to a role uses tools the role lacks, the Orchestrator knows at once, as it opens or delegates the work.": "Tools gibt es in Klassen: bei einer Rolle, die nur lesende Befehle darf, wird ein schreibender Befehl im Chat abgelehnt (hat ein Chat, der ihn ausführen darf, ihn delegiert, entscheidest du); einer, der liest, oder ein node-Skript, das in read-only-tools.md im Brain steht, erreicht dich als Berechtigung ohne „immer“. Nutzt ein an eine Rolle übergebener Skill Tools, die der Rolle fehlen, weiß es der Orchestrator sofort, wenn er die Arbeit eröffnet oder delegiert.",
  "Every role has a cartoon character recognisable even at 16 px: below 24 px the colour, the hair or headwear and the eyes stay; from 24 px the face and the prop too.": "Jede Rolle hat eine Comicfigur, die auch bei 16 px erkennbar ist: unter 24 px bleiben Farbe, Haare oder Kopfbedeckung und Augen; ab 24 px auch Gesicht und Requisit.",
  "Like the department cards of a workshop: who does what, with which tools and how far they may go without asking; the card is updated, the department stays.": "Wie die Abteilungskarten einer Werkstatt: wer was macht, mit welchen Werkzeugen und wie weit ohne Nachfragen; die Karte wird aktualisiert, die Abteilung bleibt.",
  "Tool classes: read, edit, shell, shell-read, web, browser, browser-read, mail-draft, calendar-read, brain-write, mcp (all by default). Ceilings: none (default), acceptEdits, default, plan.": "Tool-Klassen: read, edit, shell, shell-read, web, browser, browser-read, mail-draft, calendar-read, brain-write, mcp (alle standardmäßig). Grenzen: none (Standard), acceptEdits, default, plan.",
  "Instructions ≤ 8000 chars; at most 40 default skills; a role never launches itself or the Orchestrator.": "Anweisungen ≤ 8000 Zeichen; höchstens 40 Standard-Skills; eine Rolle startet nie sich selbst oder den Orchestrator.",
  "Agents page (AgentCatalogPage, the role page is AgentStudio); catalog in the main process (AgentCatalogService).": "Seite Agenten (AgentCatalogPage, die Rollenseite ist AgentStudio); Katalog im Main-Prozess (AgentCatalogService).",
  "A skill’s missing tool is reported in the answers of app_create_chat, agent_delegate and agent_catalog.": "Ein fehlendes Tool eines Skills wird in den Antworten von app_create_chat, agent_delegate und agent_catalog gemeldet.",
  "Roles and skills: the Brain section": "Rollen und Skills: der Bereich Brain",
  "Two concepts only: the role is who works, the skill is how a job is done. They keep themselves up to date, and every change is undone with one click.": "Nur zwei Begriffe: die Rolle ist, wer arbeitet, der Skill ist, wie eine Arbeit gemacht wird. Sie halten sich selbst aktuell, und jede Änderung lässt sich mit einem Klick rückgängig machen.",
  "A skill is a SKILL.md file in the brain (.claude/skills) or in your folders. A role uses its default skills and the ones its launch gives it; a skill it does not have is refused.": "Ein Skill ist eine Datei SKILL.md im Brain (.claude/skills) oder in deinen Ordnern. Eine Rolle nutzt ihre Standard-Skills und die, die ihr Start ihr gibt; ein Skill, den sie nicht hat, wird abgelehnt.",
  "The Skills tab of Memoria shows which role uses each skill and which tools it calls; \"Roles\" on a card links or drops it at once, with no approval.": "Der Skills-Tab von Memoria zeigt, welche Rolle jeden Skill nutzt und welche Tools er aufruft; „Rollen“ auf einer Karte verknüpft oder entfernt ihn sofort, ohne Genehmigung.",
  "Maintenance runs by itself every 6 hours, or at once with the \"Manutenzione\" button atop Skill, Regole and Memoria, which says what each job did: a new skill from a repeated task, duplicate skills merged, duplicate memories moved to the shared one, your corrections applied to the role, the skill or a rule. A lesson a work chat proposes waits until the Orchestrator asks you.": "Die Wartung läuft von selbst alle 6 Stunden, oder sofort mit dem Button „Wartung“ oben bei Skills, Regeln und Gedächtnis, der sagt, was jeder Job gemacht hat: ein neuer Skill aus einer wiederholten Aufgabe, doppelte Skills zusammengeführt, doppelte Erinnerungen ins gemeinsame Gedächtnis verschoben, deine Korrekturen auf Rolle, Skill oder eine Regel angewendet. Eine Lektion, die ein Arbeitschat vorschlägt, wartet, bis der Orchestrator dich fragt.",
  "Every change is logged with what, why and the evidence, and \"Undo\" puts it back. The app changes by itself only a role’s text and its skills; your yes stays for production, a role’s tools, ceiling, engine and tier, settings and texts for others.": "Jede Änderung wird mit was, warum und den Belegen protokolliert, und „Rückgängig“ stellt sie zurück. Die App ändert von selbst nur den Text einer Rolle und ihre Skills; dein Ja bleibt nötig für Produktion, Tools, Grenze, Engine und Stufe einer Rolle, Einstellungen und Texte für andere.",
  "The brain’s runbook and routines sections become skills, losing no text and never twice: the report is in Memoria’s Skills tab.": "Die Abschnitte Runbook und Routinen des Brain werden zu Skills, ohne Text zu verlieren und nie doppelt: der Bericht steht im Skills-Tab von Memoria.",
  "Rules apply to every role; Memory holds knowledge, what happened and one memory per role, with the numbers (lines per role, weekly growth, most recalled memories, stale files, recurring errors, useful or never used skills, curious facts; each \"?\" says how it is computed) and every file opens in the viewer; Map shows role → skills → rules → memory.": "Regeln gelten für jede Rolle; Gedächtnis hält Wissen, was passiert ist und ein Gedächtnis pro Rolle, mit den Zahlen (Zeilen pro Rolle, wöchentliches Wachstum, meistabgerufene Erinnerungen, veraltete Dateien, wiederkehrende Fehler, nützliche oder nie genutzte Skills, kuriose Fakten; jedes „?“ sagt, wie es berechnet wird) und jede Datei öffnet sich im Viewer; Karte zeigt Rolle → Skills → Regeln → Gedächtnis.",
  "Classifiers, read only: one card per classifier (kind of work, model, skills, estimates, cost-ledger kind) with what it decides, its numbers, the weekly trend, how much it has learned and a curious fact; a click opens the detail with the history and the tables (the model table, the suggested skills versus the ones given).": "Klassifikatoren, nur lesend: eine Karte pro Klassifikator (Art der Arbeit, Modell, Skills, Schätzungen, Art im Kostenbuch) mit dem, was er entscheidet, seinen Zahlen, dem Wochentrend, wie viel er gelernt hat und einem kuriosen Fakt; ein Klick öffnet das Detail mit dem Verlauf und den Tabellen (die Modelltabelle, die vorgeschlagenen Skills gegenüber den gegebenen).",
  "Like a team with a shared manual: the people are the roles, the manual’s pages are the skills, and someone keeps it tidy every night.": "Wie ein Team mit einem gemeinsamen Handbuch: die Leute sind die Rollen, die Seiten des Handbuchs die Skills, und jemand hält es jede Nacht in Ordnung.",
  "Change log and migration report in the app’s data folder; a role’s memory in agents/<id>/memory.md, the shared one in memory/shared.md.": "Änderungsprotokoll und Migrationsbericht im Datenordner der App; das Gedächtnis einer Rolle in agents/<id>/memory.md, das gemeinsame in memory/shared.md.",
  "IPC brainmodel:state, :maintain, :rollback, :link and classifiers:state; pages in src/renderer/components/brain-model/ (ADR 0077).": "IPC brainmodel:state, :maintain, :rollback, :link und classifiers:state; Seiten in src/renderer/components/brain-model/ (ADR 0077).",
  "The Orchestrator": "Der Orchestrator",
  "The coordinating chat in the right column: it plans, delegates to the roles and follows where they stand, without reading their work.": "Der koordinierende Chat in der rechten Spalte: er plant, delegiert an die Rollen und verfolgt, wo sie stehen, ohne ihre Arbeit zu lesen.",
  "There is only one, always in the right column (Ctrl+R). You create it: a role cannot create another.": "Es gibt nur einen, immer in der rechten Spalte (Strg+R). Du legst ihn an: eine Rolle kann keinen weiteren anlegen.",
  "It gets its role and the list of work roles (name and what each is for); it asks the role catalog for the details, never the roles’ instructions.": "Er bekommt seine Rolle und die Liste der Arbeitsrollen (Name und wofür jede da ist); die Details fragt er beim Rollenkatalog ab, nie die Anweisungen der Rollen.",
  "It opens a work chat always naming the role, with an \"Area · what\" title, the contract as the first message and the skills suggested for the request. The role decides engine and model; the Orchestrator may ask for a higher tier, up to the role’s maximum.": "Er eröffnet einen Arbeitschat immer mit Nennung der Rolle, mit einem Titel „Bereich · was“, dem Vertrag als erster Nachricht und den für die Anfrage vorgeschlagenen Skills. Die Rolle bestimmt Engine und Modell; der Orchestrator kann eine höhere Stufe verlangen, bis zum Maximum der Rolle.",
  "Before starting it estimates the request on similar finished jobs (time, cost, how many jobs, confidence, how many parts) and takes the fast path: a short question it answers itself, a quick one-part job goes to a single agent with no sub-chats; a delegation tree only for work in several parts, which costs more tokens. Each agent’s estimate is on its strip in the Grindhouse, and each job’s verdict says whether it stayed within ×2.": "Vor dem Start schätzt er die Anfrage anhand ähnlicher abgeschlossener Aufgaben (Zeit, Kosten, wie viele Aufgaben, Sicherheit, wie viele Teile) und nimmt den schnellen Weg: eine kurze Frage beantwortet er selbst, eine schnelle Aufgabe aus einem Teil geht an einen einzelnen Agenten ohne Unter-Chats; einen Delegationsbaum nur für Arbeit in mehreren Teilen, die mehr Tokens kostet. Die Schätzung jedes Agenten steht auf seinem Streifen im Grindhouse, und das Urteil jeder Aufgabe sagt, ob sie innerhalb von ×2 geblieben ist.",
  "Of its children it sees only state and numbers: never their text. The result reaches it when the child closes with its report.": "Von seinen Kindern sieht er nur Zustand und Zahlen: nie ihren Text. Das Ergebnis erreicht ihn, wenn das Kind mit seinem Bericht abschließt.",
  "A message of yours starting with \"[nuova chat]\" asks it to open a new work chat.": "Eine Nachricht von dir, die mit „[nuova chat]“ beginnt, bittet ihn, einen neuen Arbeitschat zu eröffnen.",
  "Mail from the chats reaches it sorted: now, grouped (30 s) or quiet.": "Post aus den Chats erreicht ihn sortiert: sofort, gebündelt (30 s) oder still.",
  "What the app holds back for it shows above its input: \"N novità in attesa\"; a click lists chat, kind, since when and why it waits. Looking costs it no turn.": "Was die App für ihn zurückhält, steht über seiner Eingabe: „N zurückgehaltene Neuigkeiten“; ein Klick listet Chat, Art, seit wann und warum es wartet. Das Anschauen kostet ihn keinen Turn.",
  "Like an editor-in-chief: does not write every piece, picks who writes it, knows where each one stands and reads the finished piece.": "Wie ein Chefredakteur: schreibt nicht jeden Artikel, wählt, wer ihn schreibt, weiß, wo jeder steht, und liest den fertigen Artikel.",
  "Your request": "Deine Anfrage",
  "Work chat": "Arbeitschat",
  "app_create_chat result: { chatId, title, harness, cwd, model, effort, route { source: agent, kind, area, reason, agent { id, version, chosenBy, tier?, modelFrom: role | tier | table | engine } } }.": "Ergebnis von app_create_chat: { chatId, title, harness, cwd, model, effort, route { source: agent, kind, area, reason, agent { id, version, chosenBy, tier?, modelFrom: role | tier | table | engine } } }.",
  "Up to 16 skills per delegated chat; a child never has tools or a ceiling above its launcher’s.": "Bis zu 16 Skills pro delegiertem Chat; ein Kind hat nie Tools oder eine Grenze über denen seines Starters.",
  "agent_catalog (the roles), app_create_chat with roleId and tier (opens the work), skills_suggest (the skills), task_estimate (the estimate), agent_metrics (the children’s state and numbers), agent_report (the child’s report).": "agent_catalog (die Rollen), app_create_chat mit roleId und tier (eröffnet die Arbeit), skills_suggest (die Skills), task_estimate (die Schätzung), agent_metrics (Zustand und Zahlen der Kinder), agent_report (der Bericht des Kinds).",
  "The app’s MCP on 127.0.0.1 (app_*, agent_catalog, skills_suggest, agent_metrics tools), each with its own endpoint and token.": "Der MCP der App auf 127.0.0.1 (Tools app_*, agent_catalog, skills_suggest, agent_metrics), jeder mit eigenem Endpoint und Token.",
  "Role runs": "Runs der Rollen",
  "A run is one job of a role, from start to its final report, with counters, cost and result.": "Ein Run ist eine Aufgabe einer Rolle, vom Start bis zu ihrem Abschlussbericht, mit Zählern, Kosten und Ergebnis.",
  "It starts when a chat starts with a work role; startedBy says who started it: you, the Orchestrator or the parent chat that delegated it.": "Er startet, wenn ein Chat mit einer Arbeitsrolle startet; startedBy sagt, wer ihn gestartet hat: du, der Orchestrator oder der Elternchat, der ihn delegiert hat.",
  "A delegated run carries parentRunId, its parent’s run: so the delegation tree stays readable in the metrics too.": "Ein delegierter Run trägt parentRunId, den Run seines Elternchats: so bleibt der Delegationsbaum auch in den Metriken lesbar.",
  "It counts questions, permissions and commands (once per request), reopenings, context peak, corrections and execution time.": "Er zählt Fragen, Berechtigungen und Befehle (einmal pro Anfrage), Wiedereröffnungen, Kontextspitze, Korrekturen und Ausführungszeit.",
  "It adds each turn’s cost and tokens; if a turn does not report them, the total becomes \"unknown\" (null), not zero.": "Er summiert Kosten und Tokens jedes Turns; meldet ein Turn sie nicht, wird die Summe „unbekannt“ (null), nicht null.",
  "The role’s final report (outcome, verified yes/partly/no, summary) stays on the run; an unreadable report counts as none.": "Der Abschlussbericht der Rolle (Ergebnis, geprüft ja/teilweise/nein, Zusammenfassung) bleibt am Run; ein unlesbarer Bericht zählt als keiner.",
  "It ends as completed, closed (chat closed or archived) or stale (72 hours without turns); writing to it again by hand reopens it.": "Er endet als abgeschlossen, geschlossen (Chat geschlossen oder archiviert) oder veraltet (72 Stunden ohne Turns); schreibst du wieder von Hand hinein, öffnet er sich neu.",
  "A verdict counts as evidence only if it comes from an ended, verified independent review (a Sentinel’s) in its own session (on any model: what counts is that it never saw the run’s reasoning); a parent’s opinion stays an opinion.": "Ein Urteil zählt nur als Beleg, wenn es aus einem beendeten, geprüften unabhängigen Review stammt (dem eines Sentinel) in eigener Sitzung (auf jedem Modell: entscheidend ist, dass es die Überlegungen des Runs nie gesehen hat); die Meinung eines Elternchats bleibt eine Meinung.",
  "Once the run has finished, in the expanded strip you say how it went (success, partial, failed): your verdict always wins.": "Ist der Run fertig, sagst du im aufgeklappten Streifen, wie es gelaufen ist (Erfolg, teilweise, fehlgeschlagen): dein Urteil gewinnt immer.",
  "Like a work order in a workshop: it opens, adds up hours and parts, closes with its report; if the customer comes back, it reopens.": "Wie ein Arbeitsauftrag in einer Werkstatt: er wird eröffnet, summiert Stunden und Teile, schließt mit seinem Bericht; kommt der Kunde zurück, wird er wieder eröffnet.",
  "Start": "Start",
  "Turns and requests": "Turns und Anfragen",
  "Outcome": "Ergebnis",
  "AgentRun { runId, chatId, agentId, version, goal, startedBy, startedAt, endedAt?, endReason?, outcome?, counters, costUsd | null, tokens | null, report?, tier?, parentRunId?, reviewOf?, reworkOf?, continuedFrom?, tags? }.": "AgentRun { runId, chatId, agentId, version, goal, startedBy, startedAt, endedAt?, endReason?, outcome?, counters, costUsd | null, tokens | null, report?, tier?, parentRunId?, reviewOf?, reworkOf?, continuedFrom?, tags? }.",
  "userData/agent-runs.json is the source; ChatSummary.run mirrors it; verdicts in run-feedback.json.": "userData/agent-runs.json ist die Quelle; ChatSummary.run spiegelt sie; Urteile in run-feedback.json.",
  "RUNS_MAX = 5000, RUNS_BYTES = 7,000,000, STALE_MS = 72 h.": "RUNS_MAX = 5000, RUNS_BYTES = 7.000.000, STALE_MS = 72 h.",
  "The final report is the role’s agent_report tool.": "Der Abschlussbericht ist das Tool agent_report der Rolle.",
  "Agent metrics and statistics": "Agenten-Metriken und Statistiken",
  "Each agent’s metrics from its ended runs: runs, verified successes, costs, level and performance on its card.": "Die Metriken jedes Agenten aus seinen beendeten Runs: Runs, geprüfte Erfolge, Kosten, Level und Leistung auf seiner Karte.",
  "The app observes each agent’s sessions (costs and times) for its own use; Costs no longer lists them per agent.": "Die App beobachtet die Sitzungen jedes Agenten (Kosten und Zeiten) für den eigenen Gebrauch; Kosten listet sie nicht mehr pro Agent.",
  "Main also computes per-agent and per-version metrics from ended runs in agent-runs.json and rollups of pruned runs; the Agenti page cards show ended runs, open runs and the median cost.": "Main berechnet außerdem Metriken pro Agent und pro Version aus beendeten Runs in agent-runs.json und Rollups bereinigter Runs; die Karten der Seite Agenten zeigen beendete Runs, offene Runs und die Mediankosten.",
  "On the back of the card, the agent’s costs: median cost per run and cost per verified successful run (the cost of every ended run divided by the verified successful ones), with how many runs. A missing number is a dash, with one line saying why.": "Auf der Rückseite der Karte die Kosten des Agenten: Mediankosten pro Run und Kosten pro geprüftem erfolgreichem Run (die Kosten jedes beendeten Runs geteilt durch die geprüft erfolgreichen), mit der Anzahl der Runs. Eine fehlende Zahl ist ein Strich, mit einer Zeile, warum.",
  "Each card has a level and a performance. Level: only verified successful runs count, never failed or unverified ones, and the real number is written beside it (\"Lv 6 Master · 38 verified successes\"); Lv 2 at 5, Lv 3 at 15, Lv 4 at 30 (each level asks 5 more). Performance: the average of verdicts (success 100%, partial 50%, failure 0%) weighted by who gave them (you and a review × 1, a Sentinel review graded by what happened × 0.8, the Orchestrator × 0.6, the verified parent of a delegated run × 0.5; the agent on itself does not count) and by age (half weight every 30 days); below 5 judged runs the agent is \"warming up\". The \"?\" beside each gives the formula.": "Jede Karte hat ein Level und eine Leistung. Level: nur geprüft erfolgreiche Runs zählen, nie fehlgeschlagene oder ungeprüfte, und die echte Zahl steht daneben („Lv 6 Meister · 38 geprüfte Erfolge“); Lv 2 bei 5, Lv 3 bei 15, Lv 4 bei 30 (jedes Level verlangt 5 mehr). Leistung: der Durchschnitt der Urteile (Erfolg 100 %, teilweise 50 %, Misserfolg 0 %), gewichtet danach, wer sie gab (du und ein Review × 1, ein am Geschehenen gemessenes Review des Sentinels × 0,8, der Orchestrator × 0,6, der geprüfte Eltern-Run eines delegierten Runs × 0,5; der Agent über sich selbst zählt nicht) und nach Alter (halbes Gewicht alle 30 Tage); unter 5 beurteilten Runs zeigt der Agent „Wärmt sich auf“. Das „?“ neben jedem gibt die Formel.",
  "Every role levels up without your verdicts too, when the switch \"Enable level and performance check\" is on: a run the Orchestrator opened is verified by a Sentinel review; a delegated run takes its verified parent’s verdict, when its report met every criterion, arrived before the parent ended and was not corrected, reopened, redone or rejected by the parent; the Sentinel review is graded by what happens next: your verdict on the same run, a second independent review (1 run in 10, about a tenth more cost) or a run it passed that was then reopened or redone. Silence never counts.": "Jede Rolle steigt auch ohne deine Urteile im Level, wenn der Schalter „Prüfung von Level und Leistung aktivieren“ an ist: Ein vom Orchestrator geöffneter Run wird durch ein Review des Sentinels geprüft; ein delegierter Run übernimmt das Urteil seines geprüften Eltern-Runs, wenn sein Bericht alle Kriterien erfüllte, vor dem Ende des Eltern-Runs ankam und nicht korrigiert, wieder geöffnet, neu gemacht oder vom Eltern-Run abgelehnt wurde; das Review des Sentinels wird an dem gemessen, was danach geschieht: dein Urteil über denselben Run, ein zweites unabhängiges Review (1 Run von 10, etwa ein Zehntel mehr Kosten) oder ein Run, den es durchgelassen hat und der dann wieder geöffnet oder neu gemacht wurde. Schweigen zählt nie.",
  "Like a fleet dashboard: consumption and times per vehicle, saying when a figure is missing instead of inventing it.": "Wie ein Flotten-Dashboard: Verbrauch und Zeiten pro Fahrzeug, und es sagt, wenn eine Zahl fehlt, statt sie zu erfinden.",
  "AgentMeasure { total, knownSubtotal, knownSessions, unknownSessions }; timing per category with medianMs.": "AgentMeasure { total, knownSubtotal, knownSessions, unknownSessions }; Zeiten pro Kategorie mit medianMs.",
  "Run metrics: agents:metrics IPC, also filtered by skill, app and repo tags; the session statistics stay internal (/api/agents/analytics).": "Run-Metriken: IPC agents:metrics, auch gefiltert nach Skill-, App- und Repo-Tags; die Sitzungsstatistiken bleiben intern (/api/agents/analytics).",
  "Errors, corrections and \"Learned rules\"": "Fehler, Korrekturen und „Gelernte Regeln“",
  "Agents’ errors land in the brain; the app groups them, and you can correct a line of reasoning while it happens.": "Die Fehler der Agenten landen im Brain; die App gruppiert sie, und du kannst eine Überlegung korrigieren, während sie passiert.",
  "When you correct an agent, the brain’s tools write a line to ai-errors.md; the app reads and groups, it does not write.": "Wenn du einen Agenten korrigierst, schreiben die Tools des Brain eine Zeile in ai-errors.md; die App liest und gruppiert, sie schreibt nicht.",
  "There are 11 official types (e.g. test-passato-a-torto, richiesta-fraintesa, regola-ignorata); an unreadable line is \"Unrecognised format\".": "Es gibt 11 offizielle Typen (z. B. test-passato-a-torto, richiesta-fraintesa, regola-ignorata); eine unlesbare Zeile ist „Format nicht erkannt“.",
  "A type is \"recurring\" from 2 rows up; the week is compared with the previous one.": "Ein Typ ist „wiederkehrend“ ab 2 Zeilen; die Woche wird mit der vorigen verglichen.",
  "\"Correct\" on a piece of reasoning sends the agent the quote and your fix; it is blocked while a question is open.": "„Korrigieren“ bei einer Überlegung schickt dem Agenten das Zitat und deine Korrektur; es ist gesperrt, solange eine Frage offen ist.",
  "\"Learned rules\", at the bottom of Memoria’s Rules tab, shows the brain’s self-improvement policies (estimates, model choice, thresholds) with Restore; a waiting proposal is decided in Memory → Proposals. It appears only when the brain has some.": "„Gelernte Regeln“, unten im Tab Regeln des Gedächtnisses, zeigt die Selbstverbesserungs-Richtlinien des Brain (Schätzungen, Modellwahl, Schwellen) mit Wiederherstellen; ein wartender Vorschlag wird in Gedächtnis → Vorschläge entschieden. Es erscheint nur, wenn das Brain welche hat.",
  "A rule counts as \"holding\" if its error does not reappear in the observed days: it is not proof of cause.": "Eine Regel gilt als „hält“, wenn ihr Fehler in den beobachteten Tagen nicht wiederkommt: das ist kein Beweis für die Ursache.",
  "Runs count explicit corrections and user reopenings after a valid report; metrics also include ai-errors.md entries with a runId and \"visto da: Brother\".": "Runs zählen ausdrückliche Korrekturen und Wiedereröffnungen durch dich nach einem gültigen Bericht; die Metriken enthalten auch Einträge in ai-errors.md mit einer runId und „visto da: Brother“.",
  "Like a department’s incident log: write it down, group it, write a rule, and watch whether the incident comes back.": "Wie das Störfallbuch einer Abteilung: aufschreiben, gruppieren, eine Regel schreiben und schauen, ob der Störfall wiederkommt.",
  "Correction": "Korrektur",
  "ai-errors.md": "ai-errors.md",
  "Group": "Gruppe",
  "Rule": "Regel",
  "Comes back?": "Kommt es wieder?",
  "In the brain: ai-errors.md (written by ops/tools/mem.mjs), policies read from /api/improve.": "Im Brain: ai-errors.md (geschrieben von ops/tools/mem.mjs), Richtlinien gelesen aus /api/improve.",
  "Correction quote ≤ 400 chars; a policy is judged from 20 outcomes (MIN_N).": "Korrekturzitat ≤ 400 Zeichen; eine Richtlinie wird nach 20 Ergebnissen beurteilt (MIN_N).",
  "Message: [Reasoning correction] / In your reasoning you wrote: «…» / Not like that: … ; \"At the next step\" on Claude only.": "Nachricht: [Reasoning correction] / In your reasoning you wrote: «…» / Not like that: … ; „Beim nächsten Schritt“ nur auf Claude.",
  "Brain scripts and changelog": "Brain-Skripte und Changelog",
  "Your agents’ tested scripts live in the brain, ready to reuse; every change to the brain lands in the changelog, which you read in the Log.": "Die getesteten Skripte deiner Agenten liegen im Brain, bereit zur Wiederverwendung; jede Änderung am Brain landet im Changelog, den du im Log liest.",
  "Scripts live in the brain’s scripts/ folder; their header says title, what it does, how to run it, tags and the last test.": "Skripte liegen im Ordner scripts/ des Brain; ihr Kopf nennt Titel, was es tut, wie man es ausführt, Tags und den letzten Test.",
  "Every chat can look them up before writing a new script, to reuse one that works.": "Jeder Chat kann sie nachschlagen, bevor er ein neues Skript schreibt, um eines wiederzuverwenden, das funktioniert.",
  "Without asking you: a chat adds the script it ran, the app saves a reusable command that worked with Esegui by itself, the Orchestrator fixes or deletes. Credentials are refused, a deleted one goes to scripts/.deleted/ and does not come back.": "Ohne dich zu fragen: ein Chat fügt das Skript hinzu, das er ausgeführt hat, die App speichert einen wiederverwendbaren Befehl, der mit „Ausführen“ funktioniert hat, von selbst, der Orchestrator korrigiert oder löscht. Zugangsdaten werden abgelehnt, ein gelöschtes kommt nach scripts/.deleted/ und kommt nicht zurück.",
  "Every change is a line in changelog.md: when, what, which file, who and why. The Orchestrator also logs the rules, skills and notes it changes.": "Jede Änderung ist eine Zeile in changelog.md: wann, was, welche Datei, wer und warum. Der Orchestrator protokolliert auch die Regeln, Skills und Notizen, die er ändert.",
  "Memoria’s Scripts & Queries tab shows the scripts as cards; no button runs a script. The changelog lines are on the Log page, kind \"Brain\".": "Der Tab Skripte & Abfragen von Memoria zeigt die Skripte als Karten; kein Button führt ein Skript aus. Die Changelog-Zeilen stehen auf der Seite Log, Art „Brain“.",
  "No classifier picks scripts: with a few self-describing scripts a word search is enough.": "Kein Klassifikator wählt Skripte: bei wenigen selbstbeschreibenden Skripten reicht eine Wortsuche.",
  "Like a workshop toolbox with a logbook beside it: every tool is labelled, and whoever changes one writes it down.": "Wie ein Werkzeugkasten in der Werkstatt mit einem Logbuch daneben: jedes Werkzeug ist beschriftet, und wer eines ändert, schreibt es auf.",
  "Tested script": "Getestetes Skript",
  "Orchestrator saves": "Orchestrator speichert",
  "scripts/": "scripts/",
  "changelog.md": "changelog.md",
  "Reuse": "Wiederverwendung",
  "brain_scripts (search), brain_script_add (add), brain_script_save and brain_script_delete (the Orchestrator).": "brain_scripts (suchen), brain_script_add (hinzufügen), brain_script_save und brain_script_delete (der Orchestrator).",
  "In the brain: scripts/<name>, scripts/.deleted/, changelog.md; created on the first save.": "Im Brain: scripts/<name>, scripts/.deleted/, changelog.md; beim ersten Speichern angelegt.",
  "Pages: /api/scripts, /api/script?id=…, /api/changelog; event scripts:changed.": "Seiten: /api/scripts, /api/script?id=…, /api/changelog; Event scripts:changed.",
  "A script ≤ 200 KB; the page reads the latest 500 changelog lines.": "Ein Skript ≤ 200 KB; die Seite liest die letzten 500 Changelog-Zeilen.",
  "Personal milestones": "Persönliche Meilensteine",
  "Three local milestones: first custom role, workspace set up and first confirmed result.": "Drei lokale Meilensteine: erste eigene Rolle, Arbeitsbereich eingerichtet und erstes bestätigtes Ergebnis.",
  "The milestones are: \"First custom role\", \"Workspace set up\", \"First confirmed result\".": "Die Meilensteine sind: „Erste eigene Rolle“, „Arbeitsbereich eingerichtet“, „Erstes bestätigtes Ergebnis“.",
  "They are saved in progress.json in the app’s data folder.": "Sie werden in progress.json im Datenordner der App gespeichert.",
  "Customizing a role and completing setup award the first two; the first result requires your confirmation of an eligible result.": "Eine Rolle anzupassen und die Einrichtung abzuschließen bringt die ersten beiden; das erste Ergebnis braucht deine Bestätigung eines geeigneten Ergebnisses.",
  "The panel on the Agenti page shows milestones and can be hidden; in demo or with storage errors it explains the problem.": "Das Panel auf der Seite Agenten zeigt die Meilensteine und lässt sich ausblenden; im Demo-Modus oder bei Speicherfehlern erklärt es das Problem.",
  "Like three boxes to tick as you prepare your workspace and confirm the first successful job.": "Wie drei Kästchen zum Abhaken, während du deine Arbeitsumgebung vorbereitest und den ersten erfolgreichen Auftrag bestätigst.",
  "ACHIEVEMENTS = ['first-agent', 'setup-complete', 'first-result'].": "ACHIEVEMENTS = ['first-agent', 'setup-complete', 'first-result'].",
  "userData/progress.json; ProgressService with enabled: true in the personal profile.": "userData/progress.json; ProgressService mit enabled: true im persönlichen Profil.",
  "The classifiers": "Die Klassifikatoren",
  "Where the app sorts something by itself without spending tokens: the skills that fit a task, the kind of work, the Orchestrator’s mail, sensitive commands.": "Wo die App selbst etwas sortiert, ohne Tokens auszugeben: die Skills, die zu einer Aufgabe passen, die Art der Arbeit, die Post des Orchestrators, heikle Befehle.",
  "Skills for a task: the request is compared with each brain skill’s name and description, by words (BM25) and, when the local model is ready, by meaning; the Orchestrator, or the role that delegates, passes the best ones to the role. It is advice: a role uses only the skills its launch gives it.": "Skills für eine Aufgabe: die Anfrage wird mit Name und Beschreibung jedes Brain-Skills verglichen, nach Wörtern (BM25) und, wenn das lokale Modell bereit ist, nach Bedeutung; der Orchestrator oder die delegierende Rolle gibt die besten an die Rolle weiter. Das ist ein Rat: eine Rolle nutzt nur die Skills, die ihr Start ihr gibt.",
  "Italian and English meet: a small lexicon of kinds of work (\"correggi\" = fix, \"revisiona\" = review, \"fonti\" = sources…) joins Italian requests and skills written in English.": "Italienisch und Englisch treffen sich: ein kleines Lexikon der Arbeitsarten („correggi“ = fix, „revisiona“ = review, „fonti“ = sources…) verbindet italienische Anfragen und auf Englisch geschriebene Skills.",
  "Kind of work for routing: the brain’s rules first (estimates.json), then the built-in lexicon, then \"altro\". A request that builds or fixes wins over a title that only names a topic.": "Art der Arbeit fürs Routing: zuerst die Regeln des Brain (estimates.json), dann das eingebaute Lexikon, dann „altro“. Eine Anfrage, die etwas baut oder repariert, gewinnt gegen einen Titel, der nur ein Thema nennt.",
  "Kind of work in the cost ledger (fix, QA, review, feature, research, question, other): Italian and English patterns, the kind with the most clues wins.": "Art der Arbeit im Kostenbuch (fix, QA, review, feature, research, question, other): italienische und englische Muster, die Art mit den meisten Hinweisen gewinnt.",
  "Mail for the Orchestrator: urgent → now; a request, done or error → grouped; progress only → quiet. When in doubt grouped: a request held back costs more than a wait.": "Post für den Orchestrator: dringend → sofort; eine Anfrage, erledigt oder Fehler → gebündelt; nur Fortschritt → still. Im Zweifel gebündelt: eine zurückgehaltene Anfrage kostet mehr als ein Warten.",
  "Commands: production ones (az, sqlcmd, ops scripts) ask for a second click and main checks again; for a read-only role a command counts as reading only if it is a known reader, with no chaining, redirection, subexpression or option that writes or runs (sort and uniq only after a pipe).": "Befehle: Produktionsbefehle (az, sqlcmd, ops-Skripte) verlangen einen zweiten Klick und Main prüft noch einmal; für eine nur lesende Rolle zählt ein Befehl nur dann als lesend, wenn er ein bekannter Leser ist, ohne Verkettung, Umleitung, Unterausdruck oder Option, die schreibt oder ausführt (sort und uniq nur nach einer Pipe).",
  "Others: messages you did not type (shown muted), \"Waits for work\" on the text, the load queue (CPU > 75% or free RAM < 15%). Permissions and questions are not guessed: they arrive structured from the CLI. Triaging a batch of work (an inbox, a list of tickets) is instead the Orchestrator’s, one chat per request, when you hand it one.": "Sonstiges: Nachrichten, die du nicht getippt hast (gedämpft angezeigt), „Wartet auf Arbeit“ am Text, die Lastwarteschlange (CPU > 75 % oder freier RAM < 15 %). Berechtigungen und Fragen werden nicht erraten: sie kommen strukturiert von der CLI. Einen Stapel Arbeit sichten (ein Posteingang, eine Liste von Tickets) ist dagegen Sache des Orchestrators, ein Chat pro Anfrage, wenn du ihm einen gibst.",
  "Brain → Classifiers shows five of them as cards: decisions, how often they \"get it\" (kind recognised, skills spot on, cost inside the range), how many decided chats succeeded (verified by you or a review, never a self-report), the average cost, 8 weeks of trend and the verified cases collected of the 20 needed to calibrate. Every number has a \"?\".": "Brain → Klassifikatoren zeigt fünf davon als Karten: Entscheidungen, wie oft sie „treffen“ (Art erkannt, Skills passend, Kosten im Bereich), wie viele entschiedene Chats erfolgreich waren (von dir oder einem Review geprüft, nie eine Selbstauskunft), die Durchschnittskosten, 8 Wochen Trend und die gesammelten geprüften Fälle von den 20, die zum Kalibrieren nötig sind. Jede Zahl hat ein „?“.",
  "Like mail sorting at the front desk: written rules, a \"misc\" box when it is unclear, and for a whole sack of mail you call the person whose job is sorting.": "Wie die Postsortierung am Empfang: schriftliche Regeln, ein Fach „Diverses“, wenn es unklar ist, und für einen ganzen Sack Post rufst du die Person, deren Job das Sortieren ist.",
  "Request": "Anfrage",
  "Words and lexicon": "Wörter und Lexikon",
  "Suggested skills": "Vorgeschlagene Skills",
  "Role launch": "Start der Rolle",
  "SkillSuggestions { candidates: { name, score 0–100, why }[] (at most 5, best first), mode: hybrid | words }; whoever delegates passes those from 60 up.": "SkillSuggestions { candidates: { name, score 0–100, why }[] (höchstens 5, die besten zuerst), mode: hybrid | words }; wer delegiert, gibt die ab 60 weiter.",
  "TaskKind: qa-run, review, bug-fix, ops-read, writing, triage, research-web, investigation, app-feature, orchestrator, altro.": "TaskKind: qa-run, review, bug-fix, ops-read, writing, triage, research-web, investigation, app-feature, orchestrator, altro.",
  "Request read up to 2000 characters; the local model gets 2.5 s, then the answer is words only; no token spent.": "Anfrage gelesen bis 2000 Zeichen; das lokale Modell bekommt 2,5 s, dann ist die Antwort nur nach Wörtern; kein Token ausgegeben.",
  "Skills for a task: the app MCP’s skills_suggest tool.": "Skills für eine Aufgabe: das Tool skills_suggest des App-MCP.",
  "Permissions and the permission ceiling": "Berechtigungen und die Berechtigungsgrenze",
  "When a role wants to do something sensitive, the CLI asks: the app shows you the panel and enforces the role’s ceiling.": "Will eine Rolle etwas Heikles tun, fragt die CLI: die App zeigt dir das Panel und setzt die Grenze der Rolle durch.",
  "The request comes from the engine (Claude, Cursor, or Codex for commands and file changes) and becomes a panel with the available responses.": "Die Anfrage kommt von der Engine (Claude, Cursor oder Codex für Befehle und Dateiänderungen) und wird zu einem Panel mit den verfügbaren Antworten.",
  "\"Allow always\" lasts for this session only: the app never writes Claude’s or Cursor’s settings files.": "„Immer erlauben“ gilt nur für diese Sitzung: die App schreibt nie die Einstellungsdateien von Claude oder Cursor.",
  "Modes: Ask every time, Accept edits, Automatic, Plan only, No permissions; chosen at start or from the ⋯ menu (Claude only).": "Modi: Jedes Mal fragen, Änderungen annehmen, Automatisch, Nur planen, Ohne Berechtigungen; gewählt beim Start oder im Menü ⋯ (nur Claude).",
  "A role’s ceiling can be plan, default or acceptEdits (changed on the Agenti page, after your approval): a higher mode is lowered to the ceiling.": "Die Grenze einer Rolle kann plan, default oder acceptEdits sein (geändert auf der Seite Agenten, nach deiner Genehmigung): ein höherer Modus wird auf die Grenze gesenkt.",
  "If the engine climbs above the ceiling by itself, the app sets it back; raising it by hand above the ceiling is refused.": "Steigt die Engine von selbst über die Grenze, setzt die App sie zurück; sie von Hand über die Grenze zu heben wird abgelehnt.",
  "An unreadable stored policy means \"read only, plan ceiling\".": "Eine unlesbare gespeicherte Richtlinie bedeutet „nur lesen, Grenze plan“.",
  "Like a company card with a limit: you can ask for approval, but above the limit it does not go through.": "Wie eine Firmenkarte mit Limit: du kannst um Genehmigung bitten, aber über dem Limit geht nichts durch.",
  "Role wants to act": "Rolle will handeln",
  "CLI request": "Anfrage der CLI",
  "Panel": "Panel",
  "Your answer": "Deine Antwort",
  "Claude: can_use_tool; Cursor: session/request_permission; Codex: command and file-change approvals.": "Claude: can_use_tool; Cursor: session/request_permission; Codex: Genehmigungen für Befehle und Dateiänderungen.",
  "PendingRequest { id, chatId, type: 'permission' | 'question' | 'command', tool, title, detail, input, noAlways?, alwaysRules? }.": "PendingRequest { id, chatId, type: 'permission' | 'question' | 'command', tool, title, detail, input, noAlways?, alwaysRules? }.",
  "Order: plan 0 < default 1 < acceptEdits 2 < auto 3 < bypassPermissions 4; auto and bypass cannot be a ceiling.": "Reihenfolge: plan 0 < default 1 < acceptEdits 2 < auto 3 < bypassPermissions 4; auto und bypass können keine Grenze sein.",
  "On Cursor (ACP) \"always\" is ignored and only the plan ceiling is enforced; other ceilings are \"declared, not enforced\".": "Auf Cursor (ACP) wird „immer“ ignoriert und nur die Grenze plan durchgesetzt; andere Grenzen sind „angegeben, nicht durchgesetzt“.",
  "On Codex, plan/default enforce a read-only sandbox; acceptEdits uses on-request approvals.": "Auf Codex erzwingen plan/default eine nur lesende Sandbox; acceptEdits nutzt Genehmigungen auf Anfrage.",
  "Questions and decisions": "Fragen und Entscheidungen",
  "When a chat \"waits for you\", the question stays pending until you answer: in the chat’s tile or in the questions window.": "Wenn ein Chat „auf dich wartet“, bleibt die Frage offen, bis du antwortest: in der Kachel des Chats oder im Fragenfenster.",
  "Every question, permission or command to review joins the \"pending\" list; the chat stays blocked until you answer.": "Jede Frage, Berechtigung oder jeder zu prüfende Befehl kommt in die Liste „offen“; der Chat bleibt blockiert, bis du antwortest.",
  "\"Questions in a window\" (the \"Popups\" switch at the top, off by default) opens them one at a time in a central window.": "„Fragen in einem Fenster“ (der Schalter „Pop-ups“ oben, standardmäßig aus) öffnet sie einzeln in einem zentralen Fenster.",
  "In the window you can answer in any order from the left rail; Esc means \"Answer later\", not \"deny\".": "Im Fenster kannst du in beliebiger Reihenfolge über die linke Leiste antworten; Esc bedeutet „Später antworten“, nicht „ablehnen“.",
  "If you are typing, a new question waits as a pill and appears 2 seconds after you stop.": "Tippst du gerade, wartet eine neue Frage als Pille und erscheint 2 Sekunden, nachdem du aufhörst.",
  "\"Answer later\" keeps everything in \"To answer\" with no popups; Ctrl+J opens the next thing waiting for you.": "„Später antworten“ behält alles unter „Zu beantworten“ ohne Pop-ups; Strg+J öffnet das Nächste, das auf dich wartet.",
  "Screenshots the agent names (a PNG/JPG/WebP path in the question or an option) show as thumbnails, before and after side by side; a click opens them large. Chat messages work the same way.": "Screenshots, die der Agent nennt (ein PNG/JPG/WebP-Pfad in der Frage oder einer Option), erscheinen als Vorschaubilder, vorher und nachher nebeneinander; ein Klick öffnet sie groß. Chat-Nachrichten funktionieren genauso.",
  "There is no timeout: the request goes away only if you answer, the CLI withdraws it, or you close the chat.": "Es gibt kein Timeout: die Anfrage verschwindet nur, wenn du antwortest, die CLI sie zurückzieht oder du den Chat schließt.",
  "Like sticky notes on the desk: they stay until you remove them, and you can decide to look at them after lunch.": "Wie Haftnotizen am Schreibtisch: sie bleiben, bis du sie entfernst, und du kannst beschließen, sie nach dem Mittagessen anzuschauen.",
  "Chat asks": "Chat fragt",
  "Pending": "Offen",
  "Tile or window": "Kachel oder Fenster",
  "Answer": "Antwort",
  "Chat resumes": "Chat macht weiter",
  "Answer = { kind: 'permission', allow, always?, message? } | { kind: 'question', answers }.": "Answer = { kind: 'permission', allow, always?, message? } | { kind: 'question', answers }.",
  "Setting questionsModal (default false); \"Answer later\" state in userData/answer-later.json.": "Einstellung questionsModal (Standard false); Zustand „Später antworten“ in userData/answer-later.json.",
  "Questions never wake the Orchestrator by themselves (orchestrator-wake.ts); the order is arrival order.": "Fragen wecken den Orchestrator nie von selbst (orchestrator-wake.ts); die Reihenfolge ist die des Eintreffens.",
  "The Grindhouse": "Das Grindhouse",
  "The home page: one strip per working agent, with the browsers it drives beside the expanded chat.": "Die Startseite: ein Streifen pro arbeitendem Agenten, mit den Browsern, die er steuert, neben dem aufgeklappten Chat.",
  "The page shows agent strips; pending requests appear on the strip of the relevant chat.": "Die Seite zeigt Agenten-Streifen; offene Anfragen erscheinen auf dem Streifen des betroffenen Chats.",
  "Strips are grouped by area, i.e. the last folder of the chat’s working path.": "Streifen werden nach Bereich gruppiert, d. h. nach dem letzten Ordner des Arbeitspfads des Chats.",
  "A strip with an attached browser shows a small globe. Its browsers stay folded until you press the globe: the globe also expands a collapsed strip, and the browsers sit beside the chat, or below in a narrow space, and each can go full screen. Those awaiting your intervention or maximized always show. A browser folded with the globe keeps working off screen.": "Ein Streifen mit angehängtem Browser zeigt einen kleinen Globus. Seine Browser bleiben eingeklappt, bis du den Globus drückst: der Globus klappt auch einen zugeklappten Streifen auf, und die Browser sitzen neben dem Chat, oder darunter bei wenig Platz, und jeder kann auf Vollbild gehen. Die, die auf dein Eingreifen warten oder maximiert sind, sind immer sichtbar. Ein mit dem Globus eingeklappter Browser arbeitet außerhalb des Bildschirms weiter.",
  "Under each strip appear the subagents and commands still at work, each with the name of the app agent it runs as (or \"no agent\"); finished ones leave at once (the full list stays in \"Details and collaborators\"). While a subagent works, the parent strip says \"waiting\", not \"finished\".": "Unter jedem Streifen erscheinen die Subagenten und Befehle, die noch arbeiten, jeder mit dem Namen des App-Agenten, als der er läuft (oder „kein Agent“); fertige verschwinden sofort (die ganze Liste bleibt unter „Details und Mitwirkende“). Solange ein Subagent arbeitet, sagt der Elternstreifen „wartet“, nicht „fertig“.",
  "An agent strip shows a dashed estimate, \"estimate ~4 min · ~0,12 $ · from 12 similar tasks\": the median of similar finished tasks (same agent and kind, then same kind, then same agent; at least 3), never this run’s own time or cost. Once done it becomes \"~4 min → 6 min\" with ✓ when the actual is between half and double. The \"?\" explains the computation and how accurate the estimates have been.": "Ein Agenten-Streifen zeigt eine gestrichelte Schätzung, „Schätzung ~4 Min. · ~0,12 $ · aus 12 ähnlichen Aufgaben“: der Median ähnlicher abgeschlossener Aufgaben (gleicher Agent und gleiche Art, dann gleiche Art, dann gleicher Agent; mindestens 3), nie die Zeit oder Kosten dieses Runs selbst. Wenn er fertig ist, wird daraus „~4 Min. → 6 Min.“ mit ✓, wenn der tatsächliche Wert zwischen der Hälfte und dem Doppelten liegt. Das „?“ erklärt die Berechnung und wie genau die Schätzungen waren.",
  "An agent that sent its final report to the Orchestrator and is idle completes its assignment and closes by itself after the delay set in Settings (Ctrl+K finds it). If it waits for you, a permission, colleagues or background tasks it stays open and the strip says \"Waiting for…\".": "Ein Agent, der seinen Abschlussbericht an den Orchestrator geschickt hat und untätig ist, schließt seine Aufgabe ab und schließt sich selbst nach der in den Einstellungen gesetzten Wartezeit (Strg+K findet sie). Wartet er auf dich, eine Berechtigung, Kollegen oder Hintergrundaufgaben, bleibt er offen und der Streifen sagt „Wartet auf…“.",
  "A collapsed strip shows agent, state, model and the last answer; a click anywhere on it expands it, every time, showing the conversation and the input. The effort is the agent profile’s: the strip does not show it.": "Ein zugeklappter Streifen zeigt Agent, Zustand, Modell und die letzte Antwort; ein Klick irgendwo darauf klappt ihn auf, jedes Mal, mit der Unterhaltung und der Eingabe. Der Aufwand ist der des Agentenprofils: der Streifen zeigt ihn nicht.",
  "Cloud agents (Cursor, Codex, Claude Code running in the vendor’s cloud, even with the PC off) get their own strip under the others, grouped by repository, with a \"cloud\" label and the engine. Cursor shows its messages, takes messages and stops from the app; Codex and Claude are followed on their own page (\"Open\"). \"Bring home\" takes the result into a new worktree. The Orchestrator starts one when you ask it, only on GitHub repositories with the branch already pushed.": "Cloud-Agenten (Cursor, Codex, Claude Code in der Cloud des Anbieters, auch bei ausgeschaltetem PC) bekommen ihren eigenen Streifen unter den anderen, nach Repository gruppiert, mit einem Label „cloud“ und der Engine. Cursor zeigt seine Nachrichten, nimmt Nachrichten an und stoppt aus der App; Codex und Claude verfolgst du auf ihrer eigenen Seite („Öffnen“). „Heimholen“ übernimmt das Ergebnis in einen neuen Worktree. Der Orchestrator startet einen, wenn du ihn darum bittest, nur auf GitHub-Repositorys mit bereits gepushtem Branch.",
  "Like a studio mixing desk: one fader per channel, and each one’s monitor below it.": "Wie ein Mischpult im Studio: ein Fader pro Kanal, und unter jedem sein Monitor.",
  "Page \"home\" (brain/pages/Home.tsx), strips in components/AgentStrips.tsx, order in lib/agent-order.ts; ADR 0068.": "Seite „home“ (brain/pages/Home.tsx), Streifen in components/AgentStrips.tsx, Reihenfolge in lib/agent-order.ts; ADR 0068.",
  "A strip is expanded if prefs.chatExpanded[id], its browsers if prefs.browserOpen[id] too; no saved order, no dragging.": "Ein Streifen ist aufgeklappt, wenn prefs.chatExpanded[id], seine Browser, wenn auch prefs.browserOpen[id]; keine gespeicherte Reihenfolge, kein Ziehen.",
  "A cloud agent starts from app_create_chat with where \"cloud\".": "Ein Cloud-Agent startet über app_create_chat mit where \"cloud\".",
  "Tasks and Done": "Tasks und Erledigt",
  "Tasks shows what waits for you on Azure DevOps; Done lists the tasks you asked for, newest first, with their cost.": "Tasks zeigt, was auf Azure DevOps auf dich wartet; Erledigt listet die Aufgaben, um die du gebeten hast, neueste zuerst, mit ihren Kosten.",
  "\"Tasks\" reads your PRs, reviews, work items and mentions with the devops-me.mjs reader: the one shipped with the app, or the brain’s own when it has one; read-only, zero tokens.": "„Tasks“ liest deine PRs, Reviews, Work Items und Erwähnungen mit dem Leser devops-me.mjs: dem mit der App mitgelieferten oder dem eigenen des Brain, wenn es einen hat; nur lesend, null Tokens.",
  "The read starts with \"Refresh now\" or by itself, every 15 minutes up to 2 hours, when the automatic read is on; a mention alerts you with a sound you can turn off.": "Das Lesen startet mit „Jetzt aktualisieren“ oder von selbst, alle 15 Minuten bis zu 2 Stunden, wenn das automatische Lesen an ist; eine Erwähnung meldet sich mit einem Ton, den du abschalten kannst.",
  "Every record has \"Discuss\": the Orchestrator gets a draft with title, link, state and folder; if work is needed, it opens and briefs the chat itself.": "Jeder Eintrag hat „Besprechen“: der Orchestrator bekommt einen Entwurf mit Titel, Link, Zustand und Ordner; braucht es Arbeit, eröffnet und brieft er den Chat selbst.",
  "\"Done\" lists by day, newest first, only the main tasks: the ones you or the Orchestrator started; a delegated chat is never a row of its own.": "„Erledigt“ listet nach Tag, neueste zuerst, nur die Hauptaufgaben: die, die du oder der Orchestrator gestartet habt; ein delegierter Chat ist nie eine eigene Zeile.",
  "A row’s cost is its own plus everything it started (children, grandchildren, reviews, reworks); \"n/a\" when a part has no known cost. Each day has its total.": "Die Kosten einer Zeile sind ihre eigenen plus alles, was sie gestartet hat (Kinder, Enkel, Reviews, Nacharbeiten); „k. A.“, wenn ein Teil keine bekannten Kosten hat. Jeder Tag hat seine Summe.",
  "The stand-up on top has one line per task of the last work day and today, ready to copy; the page spends no tokens and reads nothing outside the app.": "Das Stand-up oben hat eine Zeile pro Aufgabe des letzten Arbeitstags und von heute, fertig zum Kopieren; die Seite gibt keine Tokens aus und liest nichts außerhalb der App.",
  "Tasks is the work’s inbox; Done is the logbook.": "Tasks ist der Posteingang der Arbeit; Erledigt ist das Logbuch.",
  "Tasks: the tasks.json cache in the app’s data folder; Done: the app’s run store (agent-runs.json, IPC runs:macro).": "Tasks: der Cache tasks.json im Datenordner der App; Erledigt: der Run-Speicher der App (agent-runs.json, IPC runs:macro).",
  "Reads and alerts in src/main/tasks/, the pages in brain/pages/Task.tsx and Fatto.tsx. Until 19/10/2026 Tasks was called DevOps: old settings and links move to the new name by themselves (ADR 0079).": "Lesen und Meldungen in src/main/tasks/, die Seiten in brain/pages/Task.tsx und Fatto.tsx. Bis 19.10.2026 hieß Tasks DevOps: alte Einstellungen und Links wandern von selbst zum neuen Namen (ADR 0079).",
  "The first setup": "Die erste Einrichtung",
  "Nothing inside the window closes it by itself: a click outside does nothing, and you reopen it from Settings → \"Configura il mio lavoro\".": "Nichts im Fenster schließt es von selbst: ein Klick daneben bewirkt nichts, und du öffnest es wieder über Einstellungen → „Meine Arbeit einrichten“.",
  "One window, six steps: language, your AI, tools, who you are, folders and ready. Resume whenever you like.": "Ein Fenster, sechs Schritte: Sprache, deine KI, Tools, wer du bist, Ordner und fertig. Mach weiter, wann du willst.",
  "Language first: three big buttons, the system one already picked. A click changes the app’s language at once; the answers stay. The same language goes into me.md for the chats and into the new brain.": "Zuerst die Sprache: drei große Schaltflächen, die des Systems ist schon gewählt. Ein Klick ändert die Sprache der App sofort; die Antworten bleiben. Dieselbe Sprache kommt in me.md für die Chats und in das neue Brain.",
  "Your AI: one recommended, the others under \"More AI tools\". \"Collega\" opens the official sign-in in a separate window; the setup stays open and checks again by itself every few seconds. The first AI chosen is the roles’ one.": "Deine KI: eine empfohlen, die anderen unter „Weitere KIs“. „Verbinden“ öffnet die offizielle Anmeldung in einem eigenen Fenster; die Einrichtung bleibt offen und prüft alle paar Sekunden selbst nach. Die zuerst gewählte KI ist die der Rollen.",
  "Tools (GitHub, Jira, Azure DevOps): each tile creates the account and the agents’ MCP server together. It asks only for the organization or site, then a token (with the link to the page where it is made) or the browser sign-in, and tests at once: \"Works: I see N projects\" or what to do. The technical form is in Settings → Advanced.": "Tools (GitHub, Jira, Azure DevOps): jede Kachel legt Konto und MCP-Server der Agents zusammen an. Sie fragt nur nach Organisation oder Seite, dann nach einem Token (mit dem Link zur Seite, wo er erstellt wird) oder der Anmeldung im Browser, und testet sofort: „Funktioniert: Ich sehe N Projekte“ oder was zu tun ist. Das technische Formular liegt unter Einstellungen → Erweitert.",
  "Folders: always a new, empty brain in the default place (created on confirmation); the app looks for the projects folder by itself and asks only when it finds none. A brain you already have is pointed to in Settings → My workspace.": "Ordner: immer ein neues, leeres Brain am Standardort (bei der Bestätigung angelegt); den Projektordner sucht die App selbst und fragt nur, wenn sie keinen findet. Ein Brain, das du schon hast, wählst du unter Einstellungen → Mein Arbeitsbereich.",
  "Ready: goals, work areas and team are not asked here but later, in the first chat with the guide, one question at a time. Every answer is saved as a draft half a second later, so \"Più tardi\" or Esc resume on the same step.": "Fertig: Ziele, Arbeitsbereiche und Team werden nicht hier gefragt, sondern später im ersten Chat mit der Anleitung, eine Frage nach der anderen. Jede Antwort wird eine halbe Sekunde später als Entwurf gespeichert, so machen „Später“ oder Esc beim selben Schritt weiter.",
  "Language": "Sprache",
  "About you": "Über dich",
  "Ready": "Fertig",
  "Like the first day at a new office: they show you your desk, hand you the badges and check they really open the doors.": "Wie der erste Tag in einem neuen Büro: man zeigt dir deinen Schreibtisch, gibt dir die Ausweise und prüft, ob sie die Türen wirklich öffnen.",
  "Folders": "Ordner",
  "Your AI": "Deine KI",
  "Tools": "Tools",
  "The choices live in config.json (brainRoot, projectsRoot); the draft in setup.json; a new brain uses projectsRoot as its repositories folder (REPOS).": "Die Auswahl liegt in config.json (brainRoot, projectsRoot); der Entwurf in setup.json; ein neues Brain nutzt projectsRoot als seinen Repository-Ordner (REPOS).",
  "Projects search: folder names and .git presence only, at most 300 folders known to the CLIs; no file opened. Sign-in re-checks: every 4 seconds for 3 minutes.": "Projektsuche: nur Ordnernamen und ob .git vorhanden ist, höchstens 300 den CLIs bekannte Ordner; keine Datei geöffnet. Neuprüfung der Anmeldung: alle 4 Sekunden für 3 Minuten.",
  "The brain: notes and memory": "Das Brain: Notizen und Gedächtnis",
  "A folder of notes, new and empty at the first setup (or a brain you already have): agents read and write it, the app shows it live.": "Ein Ordner mit Notizen, neu und leer bei der ersten Einrichtung (oder ein Brain, das du schon hast): Agenten lesen und schreiben ihn, die App zeigt ihn live.",
  "It is recognised by brain.json (a new brain) or by AGENTS.md plus ops/tools/brain-site.mjs (an older brain); the path is saved in config.json (brainRoot).": "Es wird an brain.json erkannt (ein neues Brain) oder an AGENTS.md plus ops/tools/brain-site.mjs (ein älteres Brain); der Pfad wird in config.json gespeichert (brainRoot).",
  "A new brain holds only me.md (your profile) and brain.json: the app’s rules, skills, agents and tools stay in the app and reach every chat. now.md, ideas.md, ai-errors.md and journal/ appear on first use.": "Ein neues Brain enthält nur me.md (dein Profil) und brain.json: Regeln, Skills, Agenten und Tools der App bleiben in der App und erreichen jeden Chat. now.md, ideas.md, ai-errors.md und journal/ erscheinen bei der ersten Nutzung.",
  "Brain tools update notes through mem.mjs; the app also writes the me.md profile, mail under ops/state/inbox/, brain-settings.json and skill/agent files, as well as state in ops/state/improve/.": "Die Brain-Tools aktualisieren Notizen über mem.mjs; die App schreibt außerdem das Profil me.md, Post unter ops/state/inbox/, brain-settings.json und Skill- und Agentendateien sowie Zustand in ops/state/improve/.",
  "The live feed watches the folder and shows what changed (ideas, errors, decisions…); \"while you were away\" marks those that came while the app was closed.": "Der Live-Feed beobachtet den Ordner und zeigt, was sich geändert hat (Ideen, Fehler, Entscheidungen…); „während du weg warst“ markiert, was gekommen ist, während die App geschlossen war.",
  "Runbooks and routines of an older brain become skills once; the original files stay where they are, lines that look like credentials never pass.": "Runbooks und Routinen eines älteren Brain werden einmal zu Skills; die Originaldateien bleiben, wo sie sind, Zeilen, die wie Zugangsdaten aussehen, kommen nie durch.",
  "Several domains and sync between PCs are optional (domain.json); every push goes through the publish guard first.": "Mehrere Domänen und Sync zwischen PCs sind optional (domain.json); jeder Push geht zuerst durch den Veröffentlichungsschutz.",
  "Like a crew’s shared logbook: whoever starts a shift reads it, whoever ends one writes what happened.": "Wie das gemeinsame Logbuch einer Mannschaft: wer eine Schicht beginnt, liest es, wer eine beendet, schreibt, was passiert ist.",
  "Agent reads": "Agent liest",
  "Works": "Arbeitet",
  "mem.mjs writes": "mem.mjs schreibt",
  "Live feed": "Live-Feed",
  "Feed: watching with a 400 ms debounce, 500 events kept.": "Feed: Beobachtung mit 400 ms Debounce, 500 Events behalten.",
  "domain.json { name, scope: 'everywhere' | 'this-pc', remote?, denyList? }; no file = one \"this PC only\" domain.": "domain.json { name, scope: 'everywhere' | 'this-pc', remote?, denyList? }; keine Datei = eine Domäne „nur dieser PC“.",
  "The brain’s data server (brain-site.mjs) runs on a 127.0.0.1 port; main forwards only GETs on allowed paths.": "Der Datenserver des Brain (brain-site.mjs) läuft auf einem Port von 127.0.0.1; Main leitet nur GETs auf erlaubten Pfaden weiter.",
  "Search (Ctrl+K)": "Suche (Strg+K)",
  "Searches chats, messages, branches and brain notes; in the brain notes by meaning too, with a local, offline model.": "Durchsucht Chats, Nachrichten, Branches und Brain-Notizen; in den Brain-Notizen auch nach Bedeutung, mit einem lokalen Offline-Modell.",
  "It indexes chats of the last 30 days (open ones always), the git branches of the chats’ folders and the brain’s .md files.": "Sie indiziert die Chats der letzten 30 Tage (offene immer), die Git-Branches der Chat-Ordner und die .md-Dateien des Brain.",
  "Every word of the query must appear; case and accents do not matter.": "Jedes Wort der Suche muss vorkommen; Groß-/Kleinschreibung und Akzente sind egal.",
  "Score: a match in the title, then the whole phrase, then loose words, plus a bonus for recent things.": "Bewertung: ein Treffer im Titel, dann die ganze Phrase, dann lose Wörter, plus ein Bonus für Neues.",
  "The chats and branches index refreshes only when you search (at most every 2 seconds), with no timer or watcher.": "Der Index für Chats und Branches wird nur beim Suchen aufgefrischt (höchstens alle 2 Sekunden), ohne Timer oder Watcher.",
  "The \"In the brain\" group uses the hybrid search: words (BM25, a typo allowed too) and meaning (multilingual-e5, downloaded once then offline), so an English phrase finds an Italian note. Until the model is ready it searches by words only.": "Die Gruppe „Im Brain“ nutzt die hybride Suche: Wörter (BM25, auch ein Tippfehler erlaubt) und Bedeutung (multilingual-e5, einmal heruntergeladen, dann offline), so findet eine englische Phrase eine italienische Notiz. Bis das Modell bereit ist, sucht sie nur nach Wörtern.",
  "Results in groups: \"Chats found\", \"In messages\", \"Branches\", \"In the brain\"; at most 6 per group.": "Ergebnisse in Gruppen: „Gefundene Chats“, „In Nachrichten“, „Branches“, „Im Brain“; höchstens 6 pro Gruppe.",
  "Like a book’s index, with a librarian who, for the brain notes, also understands what you mean.": "Wie das Register eines Buchs, mit einer Bibliothekarin, die bei den Brain-Notizen auch versteht, was du meinst.",
  "Query from 2 to 200 chars; 2,000,000 chars per chat; 4000 brain files, 1 MB each.": "Suche von 2 bis 200 Zeichen; 2.000.000 Zeichen pro Chat; 4000 Brain-Dateien, je 1 MB.",
  "Title 600 + text + recency (up to 150, linear over 30 days); phrase 200; words 100.": "Titel 600 + Text + Aktualität (bis 150, linear über 30 Tage); Phrase 200; Wörter 100.",
  "Chats and branches: in-memory index in the main process (src/main/search), channel search:query. Brain: hybrid index in userData/search/index.db, in a worker, the same one /api/search and the chats’ brain_search tool use.": "Chats und Branches: In-Memory-Index im Main-Prozess (src/main/search), Kanal search:query. Brain: hybrider Index in userData/search/index.db, in einem Worker, demselben, den /api/search und das Tool brain_search der Chats nutzen.",
  "The file viewer": "Der Datei-Viewer",
  "Opens a file mentioned in a chat or the brain read-only, at the right line, only inside the working folders.": "Öffnet eine in einem Chat oder im Brain erwähnte Datei nur lesend, an der richtigen Zeile, nur innerhalb der Arbeitsordner.",
  "Allowed folders: the brain, the app’s repo folder (Settings) and the chat’s folder.": "Erlaubte Ordner: das Brain, der Repo-Ordner der App (Einstellungen) und der Ordner des Chats.",
  "It refuses files outside these folders (checked before and after resolving the real path), drive roots and network shares.": "Er lehnt Dateien außerhalb dieser Ordner ab (vor und nach dem Auflösen des echten Pfads geprüft), Laufwerkswurzeln und Netzwerkfreigaben.",
  "It does not show \"private\" files: folders starting with a dot (except .github and .githooks) or names like secret, token, password.": "Er zeigt keine „privaten“ Dateien: Ordner, die mit einem Punkt beginnen (außer .github und .githooks), oder Namen wie secret, token, password.",
  "Text up to 1 MB; .jsonl as a table; the rest as numbered code.": "Text bis 1 MB; .jsonl als Tabelle; der Rest als nummerierter Code.",
  "Markdown and HTML reports with their images (embedded as base64 or files beside the report), never from the internet; a click on an image opens it large. The HTML is cleaned: no scripts, forms or external loads.": "Markdown- und HTML-Berichte mit ihren Bildern (als base64 eingebettet oder als Dateien neben dem Bericht), nie aus dem Internet; ein Klick auf ein Bild öffnet es groß. Das HTML wird bereinigt: keine Skripte, Formulare oder externen Ladevorgänge.",
  "Clicking a path in a chat first opens a small preview (14 lines), writing and running nothing.": "Ein Klick auf einen Pfad in einem Chat öffnet zuerst eine kleine Vorschau (14 Zeilen), ohne etwas zu schreiben oder auszuführen.",
  "Like a museum display case: you look closely, but you do not touch or take it away.": "Wie eine Vitrine im Museum: du schaust genau hin, aber du berührst nichts und nimmst nichts mit.",
  "FileReference { path, line?, column?, chatId? }, from \"path:line:column\" or \"#L10C2\".": "FileReference { path, line?, column?, chatId? }, aus \"path:line:column\" oder \"#L10C2\".",
  "FILE_VIEW_BYTES = 1,000,000; png/jpg/webp images ≤ 4 MB and 4096 px a side; beyond 4000 lines a window around the cited line.": "FILE_VIEW_BYTES = 1.000.000; Bilder png/jpg/webp ≤ 4 MB und 4096 px pro Seite; ab 4000 Zeilen ein Ausschnitt um die zitierte Zeile.",
  "Channel app:readFile → readFileView in main; page \"file\" (brain/pages/FileViewer.tsx).": "Kanal app:readFile → readFileView in Main; Seite „file“ (brain/pages/FileViewer.tsx).",
  "Model routing": "Modell-Routing",
  "A table gives engine, model and effort to chats started without a role; a role’s chat takes its role tier’s model.": "Eine Tabelle gibt Chats, die ohne Rolle gestartet werden, Engine, Modell und Aufwand; der Chat einer Rolle nimmt das Modell der Stufe seiner Rolle.",
  "Kind comes from the title and first prompt unless supplied explicitly; area comes from the caller or title, with App for chats in the app’s code folder.": "Die Art kommt aus Titel und erstem Prompt, außer sie wird ausdrücklich angegeben; der Bereich kommt vom Aufrufer oder aus dem Titel, mit App für Chats im Code-Ordner der App.",
  "The most specific row wins: kind + area, then area, then kind, then \"any\"; on a tie the first one.": "Die spezifischste Zeile gewinnt: Art + Bereich, dann Bereich, dann Art, dann „beliebig“; bei Gleichstand die erste.",
  "If the row names an engine that cannot start, your \"Chats opened by the Orchestrator\" defaults apply.": "Nennt die Zeile eine Engine, die nicht starten kann, gelten deine Standards für „Vom Orchestrator geöffnete Chats“.",
  "A role is never overridden: its chat has its own model; when the role has none, the table row’s model on its engine (and its effort, when the role names none), else its tier’s model. The route records it as \"agent\". Without a role, a model other than the table’s needs a reason; max effort never from the table.": "Eine Rolle wird nie überschrieben: ihr Chat hat sein eigenes Modell; hat die Rolle keines, das Modell der Tabellenzeile auf ihrer Engine (und deren Aufwand, wenn die Rolle keinen nennt), sonst das Modell ihrer Stufe. Die Route vermerkt es als „agent“. Ohne Rolle braucht ein anderes Modell als das der Tabelle einen Grund; maximaler Aufwand nie aus der Tabelle.",
  "Your verdict on a role run (or an independent review’s) enters the ledger as a known outcome; the row’s reason shows today’s counts, for example \"16 chats, 10 with an outcome, 70% successful\".": "Dein Urteil über einen Run einer Rolle (oder das eines unabhängigen Reviews) kommt als bekanntes Ergebnis ins Buch; der Grund der Zeile zeigt die heutigen Zahlen, zum Beispiel „16 Chats, 10 mit Ergebnis, 70 % erfolgreich“.",
  "\"Exploration\" (0–50%) sometimes tries the model with the fewest samples, never for the Orchestrator and never for chats you start.": "„Erkundung“ (0–50 %) probiert manchmal das Modell mit den wenigsten Stichproben, nie für den Orchestrator und nie für Chats, die du startest.",
  "The table is a file in the brain: every save is a new version, and agents never change a «locked» row.": "Die Tabelle ist eine Datei im Brain: jedes Speichern ist eine neue Version, und eine «locked»-Zeile ändern Agenten nie.",
  "Work votes and the loop that updates the table live in the brain’s scripts (ADR 0047).": "Arbeitsbewertungen und die Schleife, die die Tabelle aktualisiert, liegen in den Skripten des Brain (ADR 0047).",
  "Like a call-centre switchboard: depending on why you call, it puts you through to the right department.": "Wie die Vermittlung eines Callcenters: je nachdem, warum du anrufst, verbindet sie dich mit der richtigen Abteilung.",
  "Title and prompt": "Titel und Prompt",
  "Kind + area": "Art + Bereich",
  "Table row": "Tabellenzeile",
  "Engine and model": "Engine und Modell",
  "Row: { kind | *, area?, harness, model, effort, why, since, evidence, locked?, onApi? }; table with exploration and costWeight (default 7).": "Zeile: { kind | *, area?, harness, model, effort, why, since, evidence, locked?, onApi? }; Tabelle mit exploration und costWeight (Standard 7).",
  "<brain>/ops/state/improve/routing/v<N>.json + current.json; prices and models in <brain>/harness/models.json, or in the app’s copy until a new brain has its own.": "<brain>/ops/state/improve/routing/v<N>.json + current.json; Preise und Modelle in <brain>/harness/models.json, oder in der Kopie der App, bis ein neues Brain seine eigene hat.",
  "EXPLORE_MIN = 20 samples; never Fable; App areas use the app chats’ engine.": "EXPLORE_MIN = 20 Stichproben; nie Fable; App-Bereiche nutzen die Engine der App-Chats.",
  "Cost and usage limits": "Kosten und Nutzungslimits",
  "The top bar shows today’s spend and the plan’s windows; spending limits warn, they do not stop.": "Die obere Leiste zeigt die heutigen Ausgaben und die Fenster des Plans; Ausgabenlimits warnen, sie stoppen nicht.",
  "At the top: today’s spend, 5-hour window, week and today’s chats from the most expensive; green below 70%, amber from 70%, red from 90%.": "Oben: heutige Ausgaben, 5-Stunden-Fenster, Woche und die heutigen Chats ab dem teuersten; grün unter 70 %, gelb ab 70 %, rot ab 90 %.",
  "Andamento → Costi is the one costs page: today’s chats live, the period with its comparison, a few curious facts (the priciest day, the model that weighs most), where to save, charts by day, kind, model and area, and every chat. Per-agent costs are on the back of its card in Agenti.": "Verlauf → Kosten ist die einzige Kostenseite: die heutigen Chats live, der Zeitraum mit seinem Vergleich, ein paar kuriose Fakten (der teuerste Tag, das Modell, das am meisten wiegt), wo du sparen kannst, Diagramme nach Tag, Art, Modell und Bereich, und jeder Chat. Die Kosten pro Agent stehen auf der Rückseite seiner Karte unter Agenten.",
  "A turn’s cost is computed from tokens at models.json prices, then replaced by the real cost the CLI reports at the end of the turn.": "Die Kosten eines Turns werden aus Tokens zu den Preisen in models.json berechnet und dann durch die echten Kosten ersetzt, die die CLI am Ende des Turns meldet.",
  "For Claude it is an API list price: on a subscription it is an equivalent cost, not an invoice.": "Für Claude ist das ein API-Listenpreis: bei einem Abo sind es gleichwertige Kosten, keine Rechnung.",
  "Spending limits (per day, per chat) warn at 80% and 100%, once each; at 100% an urgent alert comes too.": "Ausgabenlimits (pro Tag, pro Chat) warnen bei 80 % und 100 %, je einmal; bei 100 % kommt auch eine dringende Meldung.",
  "No limit stops a chat by itself.": "Kein Limit stoppt einen Chat von selbst.",
  "Claude automatically compacts context near the window configured by \"Compact Claude chats at (tokens)\", default 200,000.": "Claude komprimiert den Kontext automatisch nahe dem Fenster, das unter „Claude-Chats komprimieren bei (Tokens)“ eingestellt ist, Standard 200.000.",
  "Like a fuel gauge with the reserve light: it warns you, but the car does not switch itself off.": "Wie eine Tankanzeige mit Reservelampe: sie warnt dich, aber das Auto schaltet sich nicht selbst ab.",
  "Claude spend from <brain>/ops/tools/cost.mjs every 3 minutes; alert state in budget-state.json.": "Claude-Ausgaben aus <brain>/ops/tools/cost.mjs alle 3 Minuten; Meldungszustand in budget-state.json.",
  "Cost = (input·price + cache writes + cache reads + output·price) / 1e6, with a long-prompt tier.": "Kosten = (Input·Preis + Cache-Schreibvorgänge + Cache-Lesevorgänge + Output·Preis) / 1e6, mit einer Stufe für lange Prompts.",
  "The limits’ \"ask\" mode (stop or continue?) is described but today only adds a note to the alert.": "Der Modus „fragen“ der Limits (stoppen oder weitermachen?) ist beschrieben, fügt aber heute nur einen Hinweis zur Meldung hinzu.",
  "Connectors and MCP servers": "Konnektoren und MCP-Server",
  "In Settings → Connectors you add MCP servers once: the app gives them to Claude, Cursor and Codex, with encrypted tokens and each agent’s limits.": "Unter Einstellungen → Konnektoren fügst du MCP-Server einmal hinzu: die App gibt sie an Claude, Cursor und Codex weiter, mit verschlüsselten Tokens und den Grenzen jedes Agenten.",
  "One section: the app’s accounts (Azure DevOps, GitHub, Jira) and the MCP servers as cards, each with state, use, tools, roles and one \"Prova\".": "Ein Bereich: die Konten der App (Azure DevOps, GitHub, Jira) und die MCP-Server als Karten, jede mit Zustand, Nutzung, Tools, Rollen und einem „Testen“.",
  "A server is local (a command, e.g. npx) or remote (an https address); the token is typed once, encrypted on the computer and then shown only masked.": "Ein Server ist lokal (ein Befehl, z. B. npx) oder remote (eine https-Adresse); das Token wird einmal eingegeben, auf dem Computer verschlüsselt und danach nur maskiert gezeigt.",
  "\"Prova\" opens the server as a chat would, lists its tools (read or write) and, when it fails, says the error and how to fix it.": "„Testen“ öffnet den Server so, wie es ein Chat täte, listet seine Tools (lesen oder schreiben) und sagt, wenn es scheitert, den Fehler und wie man ihn behebt.",
  "Chats reach the servers only through the app (127.0.0.1): the token stays in the app, never in the engines’ config files.": "Chats erreichen die Server nur über die App (127.0.0.1): das Token bleibt in der App, nie in den Konfigurationsdateien der Engines.",
  "Every agent may use every server; from the back of its card you narrow it per server: everything, read only, chosen tools or nothing.": "Jeder Agent darf jeden Server nutzen; auf der Rückseite seiner Karte schränkst du es pro Server ein: alles, nur lesen, ausgewählte Tools oder nichts.",
  "A worker never has more access than the chat that started it, and a change applies at once to open chats too.": "Ein Worker hat nie mehr Zugriff als der Chat, der ihn gestartet hat, und eine Änderung gilt sofort auch für offene Chats.",
  "\"Importa da Claude e Cursor\" reads their configs without changing them and without copying secrets: you type the tokens again.": "„Aus Claude und Cursor importieren“ liest deren Konfigurationen, ohne sie zu ändern und ohne Geheimnisse zu kopieren: die Tokens gibst du neu ein.",
  "Like a hotel concierge who keeps the keys: guests ask him to open a door, and he opens only the rooms on their floor.": "Wie ein Hotelportier, der die Schlüssel verwahrt: die Gäste bitten ihn, eine Tür zu öffnen, und er öffnet nur die Zimmer auf ihrem Stockwerk.",
  "Agent’s chat": "Chat des Agenten",
  "App gateway": "App-Gateway",
  "Role access": "Zugriff der Rolle",
  "MCP server": "MCP-Server",
  "userData/mcp-servers.json (servers, per-role access, last test) and mcp-secrets.json (tokens encrypted with safeStorage).": "userData/mcp-servers.json (Server, Zugriff pro Rolle, letzter Test) und mcp-secrets.json (Tokens mit safeStorage verschlüsselt).",
  "/mcp/ext/<chat>/<server>/<token>; Claude via --mcp-config, Cursor in ACP session/new, Codex via -c mcp_servers.<id>.url.": "/mcp/ext/<chat>/<server>/<token>; Claude über --mcp-config, Cursor in ACP session/new, Codex über -c mcp_servers.<id>.url.",
  "Access per role and server: all, read, none or a list of tools; absent = all. \"Read\" = annotations.readOnlyHint.": "Zugriff pro Rolle und Server: all, read, none oder eine Liste von Tools; fehlt er = all. „Lesen“ = annotations.readOnlyHint.",
  "Servers that need an OAuth sign-in in the browser and SSE-only ones (old transport) are not supported yet.": "Server, die eine OAuth-Anmeldung im Browser brauchen, und reine SSE-Server (alter Transport) werden noch nicht unterstützt.",
  "Updates": "Updates",
  "You use a frozen stable copy. \"Aggiorna\" in Settings → Updates brings it to the latest version with one click.": "Du nutzt eine eingefrorene stabile Kopie. „Aktualisieren“ unter Einstellungen → Updates bringt sie mit einem Klick auf die neueste Version.",
  "Stable = a frozen release in %LOCALAPPDATA%/second-brain/releases; dev = anything run from the repo, with separate data.": "Stabil = ein eingefrorenes Release in %LOCALAPPDATA%/second-brain/releases; dev = alles, was aus dem Repo läuft, mit getrennten Daten.",
  "npm run promote accepts only a clean main, runs all checks and copies the build into a release that is never overwritten.": "npm run promote akzeptiert nur ein sauberes main, führt alle Prüfungen aus und kopiert den Build in ein Release, das nie überschrieben wird.",
  "If the new window does not appear within 30 seconds the release is marked bad and the previous one starts.": "Erscheint das neue Fenster nicht innerhalb von 30 Sekunden, wird das Release als schlecht markiert und das vorige startet.",
  "In the installed Windows version, 45 seconds after start the app looks for the latest release on GitHub, downloads it and checks the sha256s.": "In der installierten Windows-Version sucht die App 45 Sekunden nach dem Start das neueste Release auf GitHub, lädt es herunter und prüft die sha256-Summen.",
  "When the package is ready you see it in \"Updates\": downloaded and prepared, but not installed (automatic apply is switched off).": "Ist das Paket bereit, siehst du es unter „Updates“: heruntergeladen und vorbereitet, aber nicht installiert (automatisches Anwenden ist abgeschaltet).",
  "\"Aggiorna\" in Settings → Updates counts what is new on GitHub, then downloads it (fast-forward only), rebuilds and restarts on the latest version, without the test suite.": "„Aktualisieren“ unter Einstellungen → Updates zählt, was auf GitHub neu ist, lädt es dann herunter (nur Fast-Forward), baut neu und startet auf der neuesten Version neu, ohne die Testsuite.",
  "You can also ask the Orchestrator to \"update\": it brings the code folder to the latest version, but switching to it stays your click on \"Aggiorna\".": "Du kannst auch den Orchestrator bitten zu „aktualisieren“: er bringt den Code-Ordner auf die neueste Version, aber der Wechsel dorthin bleibt dein Klick auf „Aktualisieren“.",
  "Like changing a tyre with the spare ready: if the new one does not hold, you put the old one back.": "Wie ein Reifenwechsel mit bereitem Reserverad: hält der neue nicht, montierst du den alten wieder.",
  "Release on GitHub": "Release auf GitHub",
  "Download and verify": "Herunterladen und prüfen",
  "Prepared package": "Vorbereitetes Paket",
  "Install: not yet": "Installieren: noch nicht",
  "current.json (current, previous, bad), launch.cmd; userData second-brain (stable, MCP 4319) and second-brain-dev (dev, MCP 4329).": "current.json (current, previous, bad), launch.cmd; userData second-brain (stabil, MCP 4319) und second-brain-dev (dev, MCP 4329).",
  "Release JSON ≤ 2 MB, zip ≤ 1.5 GB, cache ≤ 4 GB; checkpoint ≤ 8 MB.": "Release-JSON ≤ 2 MB, zip ≤ 1,5 GB, Cache ≤ 4 GB; Checkpoint ≤ 8 MB.",
  "Installing the prepared package and restarting (checkpoint of drafts and preferences, then automatic rollback on failure): the code is there but switched off until the restart is verified.": "Das vorbereitete Paket installieren und neu starten (Checkpoint von Entwürfen und Einstellungen, dann automatisches Rollback bei Fehlschlag): der Code ist da, aber abgeschaltet, bis der Neustart geprüft ist.",
  "Brain maintenance": "Brain-Wartung",
  "Every 6 hours the app tidies the roles’ skills, rules and memories by itself; every change has a reason and an \"Undo\".": "Alle 6 Stunden räumt die App Skills, Regeln und Erinnerungen der Rollen selbst auf; jede Änderung hat einen Grund und ein „Rückgängig“.",
  "It runs by itself every 6 hours, spending no tokens: text work done on your PC. The \"Maintenance\" button (Skill, Rules, Memory) starts it at once.": "Sie läuft von selbst alle 6 Stunden und gibt keine Tokens aus: Textarbeit auf deinem PC. Der Button „Wartung“ (Skills, Regeln, Gedächtnis) startet sie sofort.",
  "When three or more finished jobs ask the same thing and no skill covers it, it writes a new skill; two near-identical skills become one.": "Wenn drei oder mehr abgeschlossene Aufgaben dasselbe verlangen und kein Skill es abdeckt, schreibt sie einen neuen Skill; zwei fast gleiche Skills werden zu einem.",
  "Lessons learnt from your corrections go to the role’s text, a skill or the brain’s rules; the same line in several memories goes once into the shared memory.": "Lektionen aus deinen Korrekturen gehen in den Text der Rolle, einen Skill oder die Regeln des Brain; dieselbe Zeile in mehreren Gedächtnissen kommt einmal ins gemeinsame Gedächtnis.",
  "Once, the brain’s old runbooks and \"routines\" sections become skills, with a report of where each one went.": "Einmalig werden die alten Runbooks und Abschnitte „Routinen“ des Brain zu Skills, mit einem Bericht, wo jeder gelandet ist.",
  "Every change goes to the log with what, why and the evidence; \"Undo\" puts the earlier text back, but only if nobody changed it since. An undone change is not made again.": "Jede Änderung kommt ins Protokoll mit was, warum und den Belegen; „Rückgängig“ stellt den früheren Text wieder her, aber nur, wenn ihn seitdem niemand geändert hat. Eine rückgängig gemachte Änderung wird nicht noch einmal gemacht.",
  "It never changes a role’s permissions, tools, engine, model tier or limits by itself: those become a card in Memory → Proposals.": "Sie ändert nie von selbst Berechtigungen, Tools, Engine, Modellstufe oder Grenzen einer Rolle: die werden zu einer Karte in Gedächtnis → Vorschläge.",
  "Like someone who tidies the archive at night: merges duplicates, writes the missing cards and leaves a note for everything moved, so you can put it back if you do not like it.": "Wie jemand, der nachts das Archiv aufräumt: führt Doppeltes zusammen, schreibt die fehlenden Karteikarten und hinterlässt zu allem Verschobenen einen Zettel, damit du es zurücklegen kannst, wenn es dir nicht gefällt.",
  "Finished jobs": "Abgeschlossene Aufgaben",
  "Maintenance": "Wartung",
  "Change with a reason": "Änderung mit Grund",
  "Undo if needed": "Bei Bedarf rückgängig",
  "BrainChange { id, at, job, kind: skill | agent | rule | memory, action, target, summary, reason, evidence, rolledBackAt?, canRollback }.": "BrainChange { id, at, job, kind: skill | agent | rule | memory, action, target, summary, reason, evidence, rolledBackAt?, canRollback }.",
  "userData/brain-changes.json: last 400 changes, before/after snapshots up to 256 KB each.": "userData/brain-changes.json: letzte 400 Änderungen, Vorher-/Nachher-Snapshots bis je 256 KB.",
  "Jobs: migration, upgrade, corrections, repeated-task, merge-skills, merge-memory; every 6 h, the migration and the brain upgrade a minute after start.": "Jobs: migration, upgrade, corrections, repeated-task, merge-skills, merge-memory; alle 6 h, die Migration und die Brain-Aktualisierung eine Minute nach dem Start.",
  "With a new version the brain catches up by itself: the app describes where it keeps each kind of content, and what in the notes now has a place of its own moves there, with a pointer where it was: a script to scripts/, an SQL or KQL query to queries/ (Memory → Script & Query), an idea (\"Idea:\", \"💡\", the items under \"## Ideas\") to ideas.md with the note it came from, the date and whether it was yours or the AI’s. An agent with no tools decides only when there is something to move.": "Mit einer neuen Version holt das Brain von selbst auf: Die App beschreibt, wo sie jede Art von Inhalt aufbewahrt, und was in den Notizen jetzt einen eigenen Platz hat, wandert dorthin, mit einem Verweis, wo es stand: ein Skript nach scripts/, eine SQL- oder KQL-Abfrage nach queries/ (Gedächtnis → Skripte & Abfragen), eine Idee („Idea:“, „💡“, die Punkte unter „## Ideen“) nach ideas.md, mit der Notiz, aus der sie kommt, dem Datum und ob sie deine oder die der KI war. Ein Agent ohne Werkzeuge entscheidet nur, wenn es etwas zu verschieben gibt.",
  "Memory → Proposals": "Gedächtnis → Vorschläge",
  "Everything the app proposes and that waits for your yes is a card in a single deck: one at a time, you approve or reject.": "Alles, was die App vorschlägt und auf dein Ja wartet, ist eine Karte in einem einzigen Stapel: eine nach der anderen, du gibst frei oder lehnst ab.",
  "The deck gathers proposed memory facts, skill candidates, the agents’ setting requests, the roles’ tiers and trials, the Battito’s rules, the self-improvement policies and the changes the maintenance already made in the last 14 days.": "Der Stapel sammelt vorgeschlagene Gedächtnis-Fakten, Skill-Kandidaten, Einstellungswünsche der Agenten, Stufen und Probeversionen der Rollen, Regeln des Battito, Richtlinien der Selbstverbesserung und die Änderungen, die die Wartung in den letzten 14 Tagen schon gemacht hat.",
  "Every card says who proposed it, where (chat and run), when and with what evidence; the newest is on top, the filters above split it by group.": "Jede Karte sagt, wer sie vorgeschlagen hat, wo (Chat und Lauf), wann und mit welchen Belegen; die neueste liegt oben, die Filter darüber teilen nach Gruppe.",
  "Drag right or press ✓ (→) to approve, left or ✕ (←) to reject; Z or Ctrl+Z undoes the last choice until it is sent, after about 6 seconds or at the next choice.": "Nach rechts ziehen oder ✓ (→) drücken gibt frei, nach links oder ✕ (←) lehnt ab; Z oder Strg+Z nimmt die letzte Wahl zurück, solange sie nicht gesendet ist, nach etwa 6 Sekunden oder bei der nächsten Wahl.",
  "A change already made shows as \"already applied\" with Keep or Undo: Undo is the change log’s rollback, Keep takes it off the deck.": "Eine schon gemachte Änderung erscheint als „bereits angewendet“ mit Behalten oder Rückgängig: Rückgängig ist die Wiederherstellung aus dem Änderungsprotokoll, Behalten nimmt sie aus dem Stapel.",
  "Every decision goes through its source’s usual path, and first the app checks again that the card is still open; if the source refuses, the card comes back with the reason.": "Jede Entscheidung geht über den üblichen Weg ihrer Quelle, und vorher prüft die App erneut, ob die Karte noch offen ist; lehnt die Quelle ab, kommt die Karte mit dem Grund zurück.",
  "A skill candidate can be approved only after opening its draft and evidence; the other pages no longer decide, they point here. The number beside Memory counts the open cards.": "Ein Skill-Kandidat lässt sich erst freigeben, nachdem Entwurf und Belege geöffnet wurden; die anderen Seiten entscheiden nicht mehr, sie verweisen hierher. Die Zahl neben Gedächtnis zählt die offenen Karten.",
  "Like the pile of mail on the desk: one envelope at a time, you open it, decide, move to the next, until the pile is empty.": "Wie der Poststapel auf dem Schreibtisch: ein Umschlag nach dem anderen, öffnen, entscheiden, zum nächsten, bis der Stapel leer ist.",
  "Proposal { id `<source>:<id>`, source, group, applied, title, content, facts, provenance { who, chat?, runId?, files?, at, evidence }, canApprove, canReject, blocked?, readFirst? }.": "Proposal { id `<Quelle>:<id>`, source, group, applied, title, content, facts, provenance { who, chat?, runId?, files?, at, evidence }, canApprove, canReject, blocked?, readFirst? }.",
  "IPC proposals:list, proposals:count, proposals:decide; event proposals:changed { count }. The \"Keep\" marks in userData/proposals-reviewed.json (60 days).": "IPC proposals:list, proposals:count, proposals:decide; Ereignis proposals:changed { count }. Die „Behalten“-Markierungen in userData/proposals-reviewed.json (60 Tage).",
  "Trial versions": "Probeversionen",
  "What the app does not change by itself becomes a proposal in Memory → Proposals, with the numbers before and after.": "Was die App nicht selbst ändert, wird zu einem Vorschlag in Gedächtnis → Vorschläge, mit den Zahlen vorher und nachher.",
  "The roles’ texts and skills update by themselves; model tier, tools and permissions only with your yes, on a card of Memory → Proposals (the Agents page points there).": "Texte und Skills der Rollen aktualisieren sich selbst; Modellstufe, Tools und Berechtigungen nur mit deinem Ja, auf einer Karte in Gedächtnis → Vorschläge (die Seite Agenten verweist dorthin).",
  "A trial version is compared with the version before on the same jobs (same role, same skills): up to 21 days, at least 5 jobs on each side.": "Eine Probeversion wird mit der vorigen Version bei denselben Aufgaben verglichen (gleiche Rolle, gleiche Skills): bis zu 21 Tage, mindestens 5 Aufgaben pro Seite.",
  "It proposes keeping it only when something that matters improves (success, corrections, rework) without costing, lasting or asking much more; otherwise it proposes going back.": "Sie schlägt Behalten nur vor, wenn sich etwas Wichtiges verbessert (Erfolg, Korrekturen, Nacharbeit), ohne viel mehr zu kosten, zu dauern oder zu fragen; sonst schlägt sie das Zurückgehen vor.",
  "When fewer than 60% of the jobs have an outcome, it waits: without outcomes there is nothing to compare. Your vote on the strip is what fills the comparison.": "Haben weniger als 60 % der Aufgaben ein Ergebnis, wartet sie: ohne Ergebnisse gibt es nichts zu vergleichen. Deine Bewertung auf dem Streifen ist das, was den Vergleich füllt.",
  "Every proposal says why, what changes and the numbers with how many jobs back them; you decide it, or dismiss it.": "Jeder Vorschlag sagt, warum, was sich ändert, und die Zahlen mit wie vielen Aufgaben dahinter; du entscheidest oder verwirfst ihn.",
  "Like trying a new recipe beside the old one for three weeks, on the same dishes, and deciding only once you have tasted enough.": "Wie ein neues Rezept drei Wochen lang neben dem alten auszuprobieren, bei denselben Gerichten, und erst zu entscheiden, wenn du genug gekostet hast.",
  "TRIAL_DAYS = 21 days; at least 5 comparable jobs per side; outcome coverage ≥ 60%; success −5 points = revert; cost and time within ×1.25.": "TRIAL_DAYS = 21 Tage; mindestens 5 vergleichbare Aufgaben pro Seite; Ergebnisabdeckung ≥ 60 %; Erfolg −5 Punkte = zurück; Kosten und Zeit innerhalb ×1,25.",
  "userData/agent-lifecycle.json (the proposals); the versions in role-history.json.": "userData/agent-lifecycle.json (die Vorschläge); die Versionen in role-history.json.",
  "Automatic close": "Automatisches Schließen",
  "An agent that has delivered its report and no longer works closes by itself; one waiting for something stays open and says what.": "Ein Agent, der seinen Bericht abgeliefert hat und nicht mehr arbeitet, schließt sich selbst; einer, der auf etwas wartet, bleibt offen und sagt, worauf.",
  "When a work role has sent its final report and is idle, after the time chosen in Settings (2 minutes by default) its chat is archived.": "Hat eine Arbeitsrolle ihren Abschlussbericht geschickt und ist untätig, wird ihr Chat nach der in den Einstellungen gewählten Zeit (standardmäßig 2 Minuten) archiviert.",
  "Before closing it shows a 2-minute notice on the strip: \"Keep open\" (Resta aperto) stops it.": "Vor dem Schließen zeigt sie auf dem Streifen einen Hinweis für 2 Minuten: „Offen lassen“ stoppt es.",
  "A chat waiting for your answer or a permission, colleagues, a command, background work or its own report stays open, with \"Waiting for…\".": "Ein Chat, der auf deine Antwort oder eine Berechtigung, Kollegen, einen Befehl, Hintergrundarbeit oder seinen eigenen Bericht wartet, bleibt offen, mit „Wartet auf…“.",
  "It closes only while the app is open and really sees it: no closing with the window shut or on a stale countdown.": "Er schließt sich nur, solange die App offen ist und ihn wirklich sieht: kein Schließen bei zugemachtem Fenster oder mit einem veralteten Countdown.",
  "The Orchestrator and chats without a role never close by themselves; a closed chat stays in the archive and reopens when you write to it.": "Der Orchestrator und Chats ohne Rolle schließen sich nie von selbst; ein geschlossener Chat bleibt im Archiv und öffnet sich wieder, wenn du ihm schreibst.",
  "A delegation tree closes as one: the chats that finished wait for the others, and the time starts when the last one finished.": "Ein Delegationsbaum schließt sich als Ganzes: die fertigen Chats warten auf die anderen, und die Zeit läuft ab dem Moment, in dem der letzte fertig ist.",
  "You can also close a chat from the sidebar: hover its row and press ✕ (6 seconds to undo).": "Du kannst einen Chat auch in der Seitenleiste schließen: fahr über seine Zeile und drück ✕ (6 Sekunden zum Rückgängigmachen).",
  "Like a colleague who clears the desk after handing in the work: but when waiting for your signature, stays there, paper in hand.": "Wie eine Kollegin, die den Schreibtisch räumt, nachdem sie die Arbeit abgegeben hat: wartet sie aber auf deine Unterschrift, bleibt sie da, das Blatt in der Hand.",
  "Notice AUTO_CLOSE_WARNING_MS = 120 s; window presence renewed every 15 s; time in Settings (autoCloseMin, 0 = never).": "Hinweis AUTO_CLOSE_WARNING_MS = 120 s; Anwesenheit des Fensters alle 15 s erneuert; Zeit in den Einstellungen (autoCloseMin, 0 = nie).",
  "AutoCloseStatus { chatId, deadline, warningStartedAt, keptOpen, reason, waitingFor? }; waitingFor: answer | permission | command | user | colleagues | work | report | mail | browser.": "AutoCloseStatus { chatId, deadline, warningStartedAt, keptOpen, reason, waitingFor? }; waitingFor: answer | permission | command | user | colleagues | work | report | mail | browser.",
  "The Log": "Das Log",
  "One page with everything the app does, live and readable: each task step by step, the classifiers, the estimates, the errors and memory written to the brain, Battito.": "Eine Seite mit allem, was die App tut, live und lesbar: jede Aufgabe Schritt für Schritt, die Klassifikatoren, die Schätzungen, die Fehler und das ins Brain geschriebene Gedächtnis, Battito.",
  "Each task is a chain: who chose which agent and why, its work with cost, tools and errors, the result, the verification (or \"not done\").": "Jede Aufgabe ist eine Kette: wer welchen Agenten gewählt hat und warum, seine Arbeit mit Kosten, Tools und Fehlern, das Ergebnis, die Prüfung (oder „nicht erfolgt“).",
  "App rules flag anomalies by themselves: a duplicate reply, a hidden approval (a permission closed without your answer), a review without a verdict.": "App-Regeln markieren Auffälligkeiten selbst: eine doppelte Antwort, eine versteckte Freigabe (eine Berechtigung ohne deine Antwort geschlossen), eine Überprüfung ohne Urteil.",
  "Reading it spends no tokens: these are events and counters the app saved. Only \"Fai analizzare all’AI\" prepares a message for the Orchestrator, sent only if you send it.": "Das Lesen kostet keine Tokens: das sind Events und Zähler, die die App gespeichert hat. Nur „Von der KI analysieren lassen“ bereitet eine Nachricht für den Orchestrator vor, die nur geschickt wird, wenn du sie schickst.",
  "It cleans itself: it keeps 7 days and at most 20 MB, the rest is deleted.": "Es räumt sich selbst auf: es behält 7 Tage und höchstens 20 MB, der Rest wird gelöscht.",
  "Like a plane’s black box, but written in plain words and readable while you fly.": "Wie die Blackbox eines Flugzeugs, aber in einfachen Worten geschrieben und lesbar, während du fliegst.",
  "userData/activity/log-YYYY-MM-DD.jsonl, one JSON line per event, secrets redacted.": "userData/activity/log-YYYY-MM-DD.jsonl, eine JSON-Zeile pro Event, Geheimnisse geschwärzt.",
  "IPC log:list (the last 3000 events) and event log:events (live); page G N.": "IPC log:list (die letzten 3000 Events) und Event log:events (live); Seite G N.",
  "7 days, 20 MB in all, 2000 characters per field.": "7 Tage, insgesamt 20 MB, 2000 Zeichen pro Feld.",
  "Held news": "Zurückgehaltene Neuigkeiten",
  "\"N news waiting\": news from the jobs the app has not passed to the Orchestrator yet, and why.": "„N zurückgehaltene Neuigkeiten“: Neuigkeiten aus den Aufgaben, die die App noch nicht an den Orchestrator weitergegeben hat, und warum.",
  "A job that finishes, fails, asks something or writes to the Orchestrator makes a piece of news; the app delivers it to the Orchestrator, but not always at once.": "Eine Aufgabe, die fertig wird, scheitert, etwas fragt oder dem Orchestrator schreibt, erzeugt eine Neuigkeit; die App stellt sie dem Orchestrator zu, aber nicht immer sofort.",
  "It holds it while the Orchestrator waits for you, groups it for 30 seconds with the others arriving, or lets quiet news ride along with the next delivery: so the Orchestrator is not woken at every line.": "Sie hält sie zurück, solange der Orchestrator auf dich wartet, bündelt sie 30 Sekunden mit den anderen, die eintreffen, oder lässt stille Neuigkeiten mit der nächsten Zustellung mitfahren: so wird der Orchestrator nicht bei jeder Zeile geweckt.",
  "On the Orchestrator’s column you see how many there are; a click lists them (chat, kind, since when, why it waits) and a row opens its chat.": "In der Spalte des Orchestrators siehst du, wie viele es sind; ein Klick listet sie (Chat, Art, seit wann, warum sie wartet) und eine Zeile öffnet ihren Chat.",
  "A row you open is read: it leaves the list and no longer wakes the Orchestrator, which gets it only with the next delivery. Looking at the list spends nothing.": "Eine Zeile, die du öffnest, ist gelesen: sie verlässt die Liste und weckt den Orchestrator nicht mehr, der sie erst mit der nächsten Zustellung bekommt. Die Liste anzuschauen kostet nichts.",
  "When a role the Orchestrator opened for your question has the answer, a green notice with the summary and \"Open\" shows in the Orchestrator’s chat: no extra Orchestrator turn.": "Hat eine Rolle, die der Orchestrator für deine Frage eröffnet hat, die Antwort, erscheint im Chat des Orchestrators ein grüner Hinweis mit der Zusammenfassung und „Öffnen“: kein zusätzlicher Turn des Orchestrators.",
  "Like the mail the front desk keeps aside while you are in a meeting: nothing is lost, it all arrives together when you come out.": "Wie die Post, die der Empfang beiseitelegt, während du in einer Besprechung bist: nichts geht verloren, alles kommt zusammen an, wenn du herauskommst.",
  "Grouping ORCHESTRATOR_GROUP_MS = 30 s.": "Bündelung ORCHESTRATOR_GROUP_MS = 30 s.",
  "Queues: OrchestratorWake (job news) and ChatMail (mail); read by HeldNewsHub (IPC orchestrator:held).": "Warteschlangen: OrchestratorWake (Neuigkeiten der Aufgaben) und ChatMail (Post); gelesen von HeldNewsHub (IPC orchestrator:held).",
  "Context and hand-off of a long chat": "Kontext und Übergabe eines langen Chats",
  "A chat re-reads its whole history at every step: the longer, the costlier. The app summarises it or restarts it from a hand-off note.": "Ein Chat liest bei jedem Schritt seinen ganzen Verlauf neu: je länger, desto teurer. Die App fasst ihn zusammen oder startet ihn aus einer Übergabenotiz neu.",
  "The context bar on the strip turns amber when the chat is near its limit (80% of the window; for Cursor the threshold in Settings, 200k tokens by default).": "Die Kontextleiste auf dem Streifen wird gelb, wenn der Chat nahe an seiner Grenze ist (80 % des Fensters; für Cursor die Schwelle in den Einstellungen, standardmäßig 200k Tokens).",
  "A Claude chat at its limit summarises itself in the same session; the Orchestrator also once on each new day.": "Ein Claude-Chat an seiner Grenze fasst sich in derselben Sitzung selbst zusammen; der Orchestrator außerdem einmal an jedem neuen Tag.",
  "A work chat idle for a while (50 minutes by default) writes a note while its short-term cache is still warm; your next message starts from that note instead of re-reading everything.": "Ein Arbeitschat, der eine Weile untätig ist (standardmäßig 50 Minuten), schreibt eine Notiz, solange sein Kurzzeit-Cache noch warm ist; deine nächste Nachricht startet von dieser Notiz, statt alles neu zu lesen.",
  "\"Resume\" asks the chat for a hand-off note (state, files, decisions, what was tried, next step) and opens a new chat that starts from it.": "„In neuem Chat fortsetzen“ bittet den Chat um eine Übergabenotiz (Zustand, Dateien, Entscheidungen, was versucht wurde, nächster Schritt) und öffnet einen neuen Chat, der davon ausgeht.",
  "When the chat cannot answer, the app writes the note from what it saw (files, commands, last messages) and says so.": "Kann der Chat nicht antworten, schreibt die App die Notiz aus dem, was sie gesehen hat (Dateien, Befehle, letzte Nachrichten), und sagt das.",
  "Like a shift change on a ward: instead of re-reading the whole log, whoever arrives reads the hand-over page.": "Wie ein Schichtwechsel auf einer Station: statt das ganze Protokoll neu zu lesen, liest, wer ankommt, das Übergabeblatt.",
  "Amber at 80% of the window (NEAR_COMPACTION); contextWarnTokens = 200,000; coldHandoffMin = 50; note at most 6000 chars.": "Gelb bei 80 % des Fensters (NEAR_COMPACTION); contextWarnTokens = 200.000; coldHandoffMin = 50; Notiz höchstens 6000 Zeichen.",
  "userData/handoffs/<chatId>.md.": "userData/handoffs/<chatId>.md.",
  "The Quality page": "Die Seite Qualität",
  "Four numbers on how the AI works, each with its source, the days it covers and the next step.": "Vier Zahlen dazu, wie die KI arbeitet, jede mit ihrer Quelle, den Tagen, die sie abdeckt, und dem nächsten Schritt.",
  "Errors you had to catch yourself per 100 turns: the ai-errors.md rows \"seen by\" you, divided by the turns finished in the app on the same days.": "Fehler, die du selbst erwischen musstest, pro 100 Turns: die Zeilen in ai-errors.md, „visto da“ dir, geteilt durch die in der App an denselben Tagen beendeten Turns.",
  "Rules that worked: for each rule born from an error, whether the same kind of error came back within 14 days. A young rule is \"too early\".": "Regeln, die gewirkt haben: für jede aus einem Fehler entstandene Regel, ob dieselbe Art von Fehler innerhalb von 14 Tagen wiederkam. Eine junge Regel ist „zu früh“.",
  "PRs held by a failed build or QA, and resolved bugs sent back to open (from Azure DevOps, read only).": "PRs, die durch einen fehlgeschlagenen Build oder QA aufgehalten wurden, und gelöste Bugs, die wieder auf offen gesetzt wurden (aus Azure DevOps, nur lesend).",
  "Under the numbers, the errors that repeat grouped by kind, with this week against the one before.": "Unter den Zahlen die sich wiederholenden Fehler nach Art gruppiert, diese Woche gegenüber der davor.",
  "Every number says where it comes from and on how many cases; when the cases are few it says so instead of showing a percentage.": "Jede Zahl sagt, woher sie kommt und auf wie vielen Fällen sie beruht; sind die Fälle wenige, sagt sie das, statt einen Prozentsatz zu zeigen.",
  "Like a workshop’s dashboard that counts the customers’ returns, not the compliments: few numbers, all checkable.": "Wie das Dashboard einer Werkstatt, das die Reklamationen der Kunden zählt, nicht die Komplimente: wenige Zahlen, alle überprüfbar.",
  "ai-errors.md in the brain; turns from the app’s logs (14 days); reopened bugs from ops/tools/bug-reopen.mjs, at most every 12 h.": "ai-errors.md im Brain; Turns aus den Logs der App (14 Tage); wieder geöffnete Bugs aus ops/tools/bug-reopen.mjs, höchstens alle 12 h.",
  "Quality page (sidebar → Trends, or G Q); data from /api/tables and /api/quality.": "Seite Qualität (Seitenleiste → Verlauf, oder G Q); Daten aus /api/tables und /api/quality.",
  "Memoria, one place": "Gedächtnis, ein einziger Ort",
  "Memoria is the one place for everything the brain holds: its top is alive (the day’s sentence, live counters, the latest changes, \"Maintenance\"), below it the tabs Proposals, Approved, Skills, Rules, Scripts & Queries, Ideas, Files, Learning and Statistics.": "Memoria ist der eine Ort für alles, was das Brain enthält: oben lebendig (der Satz des Tages, Live-Zähler, die letzten Änderungen, „Wartung“), darunter die Tabs Vorschläge, Freigegeben, Skills, Regeln, Skripte & Abfragen, Ideen, Dateien, Lernen und Statistik.",
  "Skills, Rules, Scripts, Ideas and Learning are no longer pages of their own in the rail: they are Memoria tabs; old links, ids and G keys (G S, G L, G T, G I, G J) open the right tab, and \"memoria/<tab>\" opens a tab from a link.": "Skills, Regeln, Skripte, Ideen und Lernen sind keine eigenen Seiten in der Leiste mehr: sie sind Tabs von Memoria; alte Links, IDs und G-Tasten (G S, G L, G T, G I, G J) öffnen den richtigen Tab, und „memoria/<tab>“ öffnet einen Tab über einen Link.",
  "The Memoria entry in the rail carries the number of proposals waiting for you; the Proposals tab shows them one at a time.": "Der Eintrag Memoria in der Leiste trägt die Zahl der Vorschläge, die auf dich warten; der Tab Vorschläge zeigt sie einzeln.",
  "\"Approved\" lists everything in the brain now (skills, rules, confirmed facts, scripts): the bin takes one out in a click and for a few seconds \"Undo\" puts it back; skills, rules and scripts go through the change log, so they stay undoable in Learning too.": "„Freigegeben“ listet alles, was jetzt im Brain ist (Skills, Regeln, bestätigte Fakten, Skripte): der Papierkorb nimmt eines mit einem Klick heraus, und ein paar Sekunden lang stellt „Rückgängig“ es wieder her; Skills, Regeln und Skripte laufen über das Änderungsprotokoll und bleiben so auch unter Lernen rückgängig machbar.",
  "\"Ideas\" splits yours from the AI’s (the \"Chi\" column of ideas.md: \"IA\" is the AI) and \"Dust one off\" brings back an old idea still open at random; below, the Pulse and the ideas’ themes.": "„Ideen“ trennt deine von denen der KI (die Spalte „Chi“ in ideas.md: „IA“ ist die KI), und „Wieder hervorholen“ bringt zufällig eine alte, noch offene Idee zurück; darunter der Puls und die Themen der Ideen.",
  "The Dashboard is gone: the sentence and the counters are at the top of Memoria, the chats’ context in Costi, the app’s errors and the errors’ themes in Quality, the AI’s tips in Ideas; the rest were duplicates.": "Das Dashboard gibt es nicht mehr: der Satz und die Zähler stehen oben in Memoria, der Kontext der Chats in Kosten, die Fehler der App und die Themen der Fehler in Qualität, die Hinweise der KI in Ideen; der Rest waren Doppelungen.",
  "Every number has a \"?\" saying how it is computed; every panel has \"Discuss\", which drafts for the Orchestrator and never sends.": "Jede Zahl hat ein „?“, das sagt, wie sie berechnet wird; jedes Panel hat „Besprechen“, das einen Entwurf für den Orchestrator vorbereitet und ihn nie selbst sendet.",
  "Like the study at home where you keep everything: the desk with the mail to open, tidy shelves and a drawer you now and then fish an idea out of.": "Wie das Arbeitszimmer zu Hause, in dem du alles aufbewahrst: der Schreibtisch mit der Post zum Öffnen, aufgeräumte Regale und eine Schublade, aus der du ab und zu eine Idee herausfischst.",
  "Tabs in lib/memory-hub.ts (HUB_TABS, parseHubArg, hubRedirect), redirect in actions.ts go(); page components/brain-model/MemoryPage.tsx; ADR 0122.": "Tabs in lib/memory-hub.ts (HUB_TABS, parseHubArg, hubRedirect), Umleitung in actions.ts go(); Seite components/brain-model/MemoryPage.tsx; ADR 0122.",
  "The bin calls brainmodel:remove (brain skills, rules/ files, scripts) and gets the change id back; \"Undo\" is brainmodel:rollback. A confirmed fact is erased with memory:delete only once its message expires.": "Der Papierkorb ruft brainmodel:remove auf (Skills des Brains, Dateien in rules/, Skripte) und bekommt die ID der Änderung zurück; „Rückgängig“ ist brainmodel:rollback. Ein bestätigter Fakt wird mit memory:delete erst gelöscht, wenn seine Meldung abläuft.",
};
